// Extraido literalmente de SirEdwards_Quiz_v1_1.html (Fase 2 - sin modificar contenido)
// Cargado como script clasico (no ES Module) para no alterar el scope global.

const QUESTIONS = [
  {"n": 21, "q": "¿Cuáles eran las tres embarcaciones de la expedición de Colón en su primer viaje a América?", "a": "La Santa María, la Pinta y la Niña", "cat": "historia", "dif": "medio", "sabias": "La Santa María encalló en la Navidad de 1492 y con sus maderas se levantó el fuerte de La Navidad, en la actual Haití.", "alias": ["Santa María, Pinta y Niña", "La Pinta, la Niña y la Santa María"]},
  {"n": 22, "q": "¿Qué invento de Gutenberg revolucionó la difusión de los libros en Europa?", "a": "La imprenta de tipos móviles", "cat": "historia", "dif": "medio", "sabias": "Su obra más famosa es la Biblia de 42 líneas, impresa hacia 1455.", "lz": "A"},
  {"n": 23, "q": "¿Qué famosa batalla de 1815 marcó la derrota final de Napoleón Bonaparte?", "a": "Waterloo", "cat": "historia", "dif": "medio", "sabias": "Tras ella fue enviado al exilio en la remota isla de Santa Elena, donde murió en 1821.", "alias": ["Batalla de Waterloo"], "lz": "A", "par": [413]},
  {"n": 24, "q": "¿Qué pueblo mesopotámico inventó la escritura cuneiforme?", "a": "Los sumerios", "cat": "historia", "dif": "medio", "sabias": "Escribían con una caña sobre tablillas de arcilla: «cuneiforme» significa «en forma de cuña».", "alias": ["Sumeria", "Civilización sumeria"], "lz": "A"},
  {"n": 25, "q": "¿Qué documento inglés de 1215 es un antecedente fundamental de la limitación del poder del monarca?", "a": "La Carta Magna", "cat": "historia", "dif": "medio", "sabias": "Se selló en 1215 bajo presión de los barones rebeldes, y el papa la anuló a los pocos meses.", "lz": "A", "alias": ["Magna Carta"]},
  {"n": 26, "q": "¿Qué emperador fue depuesto en 476 d. C., hecho que se toma como final del Imperio romano de Occidente?", "a": "Rómulo Augústulo", "cat": "historia", "dif": "dificil", "sabias": "Lo depuso Odoacro, que envió las insignias imperiales al emperador de Oriente.", "alias": ["Augústulo"]},
  {"n": 27, "q": "¿Quién fue el líder militar cartaginés que cruzó los Alpes con elefantes?", "a": "Aníbal Barca", "cat": "historia", "dif": "medio", "sabias": "Nunca conquistó Roma, aunque aplastó a sus ejércitos en Cannas.", "lz": "A"},
  {"n": 28, "q": "¿Qué tratado firmado en 1919 estableció las condiciones de paz con Alemania tras la Primera Guerra Mundial?", "a": "El Tratado de Versalles", "cat": "historia", "dif": "medio", "sabias": "Se firmó el 28 de junio de 1919, cinco años después del atentado de Sarajevo.", "lz": "A"},
  {"n": 29, "q": "¿Quién fue el conquistador español que lideró la conquista del Imperio inca?", "a": "Francisco Pizarro", "cat": "historia", "dif": "medio", "sabias": "Atahualpa pagó como rescate una habitación llena de oro, y aun así fue ejecutado.", "lz": "A"},
  {"n": 30, "q": "¿Qué monarcas, conocidos como los Reyes Católicos, gobernaron conjuntamente Castilla y Aragón?", "a": "Isabel I de Castilla y Fernando II de Aragón", "cat": "historia", "dif": "medio", "sabias": "Se casaron en 1469, pero Castilla y Aragón siguieron teniendo sus propias leyes y aduanas.", "alias": ["Isabel y Fernando", "Fernando e Isabel", "Isabel de Castilla y Fernando de Aragón"]},
  {"n": 31, "q": "¿Qué dos hermanos fueron, según la tradición romana, los fundadores de Roma?", "a": "Rómulo y Remo", "cat": "historia", "dif": "medio", "sabias": "La tradición fecha la fundación el 21 de abril del 753 a. C.; aún hoy Roma celebra su cumpleaños ese día.", "lz": "B"},
  {"n": 32, "q": "¿Qué guerra europea entre católicos y protestantes terminó en 1648?", "a": "La guerra de los Treinta Años", "cat": "historia", "dif": "medio", "sabias": "Empezó en 1618, cuando nobles protestantes checos lanzaron por una ventana de Praga a dos regentes del emperador, que sobrevivieron.", "lz": "B", "par": [48]},
  {"n": 33, "q": "¿Qué batalla de 1066 decidió la conquista normanda de Inglaterra?", "a": "La batalla de Hastings", "cat": "historia", "dif": "medio", "sabias": "Se libró el 14 de octubre de 1066; Guillermo se coronó rey en Navidad.", "lz": "A", "alias": ["Hastings", "Batalla de Hastings"]},
  {"n": 34, "q": "¿Qué gran construcción de Pekín fue el palacio imperial de los emperadores chinos durante casi cinco siglos?", "a": "La Ciudad Prohibida", "cat": "historia", "dif": "medio", "sabias": "Tiene casi 1.000 edificios repartidos por unas 72 hectáreas.", "lz": "A"},
  {"n": 35, "q": "¿Qué guerra, iniciada en 1775, acabó con el dominio británico sobre las Trece Colonias?", "a": "La Guerra de Independencia estadounidense", "cat": "historia", "dif": "medio", "sabias": "España también ayudó: Bernardo de Gálvez tomó Pensacola a los británicos en 1781.", "alias": ["Guerra de Independencia de Estados Unidos", "Revolución americana", "Guerra de Independencia americana", "Revolución estadounidense", "Guerra de Independencia estadounidense"], "lz": "B"},
  {"n": 36, "q": "¿Qué acontecimiento financiero de octubre de 1929 marcó el inicio de la Gran Depresión?", "a": "El crac de la Bolsa de Nueva York", "cat": "historia", "dif": "medio", "sabias": "El día 24 se llamó «jueves negro», pero el pánico mayor llegó el martes 29, con unos 16 millones de acciones vendidas.", "alias": ["Crac del 29", "Crack del 29"], "lz": "B"},
  {"n": 37, "q": "¿Cómo se denomina el proceso político español iniciado tras la muerte de Franco que condujo a la democracia?", "a": "La Transición española", "cat": "historia", "dif": "medio", "sabias": "El Partido Comunista se legalizó el Sábado Santo de 1977, y las primeras elecciones libres fueron ese año, el 15 de junio.", "lz": "B", "alias": ["La Transición", "Transición democrática"]},
  {"n": 38, "q": "¿Qué economista escocés publicó en 1776 La riqueza de las naciones?", "a": "Adam Smith", "cat": "historia", "dif": "medio", "sabias": "Smith habló de la «mano invisible», pero la menciona una sola vez en esta obra.", "lz": "A"},
  {"n": 39, "q": "¿Qué conflicto enfrentó a Atenas y Esparta durante gran parte del siglo V a. C.?", "a": "La Guerra del Peloponeso", "cat": "historia", "dif": "medio", "sabias": "Atenas perdió tras casi 30 años de guerra, entre 431 y 404 a. C.", "lz": "A"},
  {"n": 40, "q": "¿Cómo se llamó la parte de la península ibérica bajo dominio musulmán?", "a": "Al-Ándalus", "cat": "historia", "dif": "medio", "sabias": "En el 711 Táriq ibn Ziyad cruzó el estrecho; Gibraltar viene de «Yabal Tariq», el monte de Táriq.", "lz": "A"},
  {"n": 41, "q": "¿Qué pueblo escandinavo colonizó buena parte de Europa entre los siglos VIII y XI?", "a": "Vikingos", "cat": "historia", "dif": "medio", "sabias": "Llegaron a Norteamérica hacia el año 1000, casi cinco siglos antes que Colón.", "lz": "A"},
  {"n": 42, "q": "¿Qué científico griego ideó máquinas de defensa durante el asedio romano de Siracusa, en el siglo III a. C.?", "a": "Arquímedes", "cat": "historia", "dif": "medio", "sabias": "Cuenta la leyenda que gritó «¡Eureka!» al descubrir en la bañera el principio de la flotación.", "alias": ["Arquímedes de Siracusa"], "lz": "A"},
  {"n": 43, "q": "¿Qué batalla naval de 1805 confirmó el dominio británico de los mares durante las guerras napoleónicas?", "a": "La batalla de Trafalgar", "cat": "historia", "dif": "medio", "sabias": "Nelson murió en pleno combate, herido por un tirador francés apostado en lo alto de otro buque, el Redoutable.", "lz": "A"},
  {"n": 44, "q": "¿Qué acontecimiento de 1453 marcó tradicionalmente el final de la Edad Media?", "a": "La caída de Constantinopla", "cat": "historia", "dif": "medio", "sabias": "Los otomanos usaron enormes cañones contra unas murallas que llevaban más de mil años en pie.", "lz": "B", "par": [337]},
  {"n": 45, "q": "¿Qué guerra europea estalló a principios del siglo XVIII tras morir sin hijos Carlos II de España?", "a": "La Guerra de Sucesión Española", "cat": "historia", "dif": "medio", "sabias": "Lo apodaron «el Hechizado»: se creía que sus males eran obra de un maleficio.", "lz": "B", "par": [51]},
  {"n": 46, "q": "¿Qué conflicto enfrentó a los estados del norte y del sur de Estados Unidos entre 1861 y 1865?", "a": "La Guerra de Secesión", "cat": "historia", "dif": "medio", "sabias": "Fue la guerra más mortífera de la historia de EE. UU., con más de 600.000 soldados muertos.", "lz": "A"},
  {"n": 47, "q": "¿Cómo se llamaba la red de rutas comerciales entre China y Europa?", "a": "La Ruta de la Seda", "cat": "historia", "dif": "medio", "sabias": "El nombre lo inventó en 1877 el geógrafo alemán Ferdinand von Richthofen.", "lz": "A"},
  {"n": 48, "q": "¿Qué conjunto de tratados de 1648 puso fin a la mayor guerra de religión de Europa?", "a": "La Paz de Westfalia", "cat": "historia", "dif": "dificil", "sabias": "Se negoció a la vez en Münster y Osnabrück: las delegaciones católicas y las protestantes trataron por separado.", "lz": "B", "par": [32]},
  {"n": 49, "q": "¿Qué conferencia de 1884-1885 fijó las reglas del reparto colonial de África entre potencias europeas?", "a": "La Conferencia de Berlín", "cat": "historia", "dif": "dificil", "sabias": "Ningún representante africano participó, aunque se decidía el futuro del continente.", "lz": "B"},
  {"n": 50, "q": "¿Qué doctrina del siglo XIX, basada en la lucha de clases, inspiró la Revolución rusa?", "a": "El marxismo", "cat": "historia", "dif": "medio", "sabias": "El Manifiesto Comunista, de 1848, empieza con «Un fantasma recorre Europa»."},
  {"n": 51, "q": "¿Qué tratado de 1713 reconoció a Felipe V como rey de España?", "a": "El Tratado de Utrecht", "cat": "historia", "dif": "dificil", "sabias": "Gran Bretaña obtuvo Gibraltar y Menorca, entre otras concesiones, tras la guerra.", "lz": "A", "par": [45]},
  {"n": 52, "q": "¿Qué tratado de 1494 estableció una línea de demarcación entre las zonas de expansión de Castilla y Portugal?", "a": "El Tratado de Tordesillas", "cat": "historia", "dif": "dificil", "sabias": "Portugal y Castilla se repartieron el mundo con una línea trazada a 370 leguas de Cabo Verde.", "lz": "A"},
  {"n": 53, "q": "¿Qué plan estadounidense de 1947 financió la reconstrucción de Europa tras la Segunda Guerra Mundial?", "a": "El Plan Marshall", "cat": "historia", "dif": "dificil", "sabias": "EE. UU. ofreció la ayuda también a la URSS, que la rechazó.", "lz": "A"},
  {"n": 54, "q": "¿Qué acontecimiento de 1917 llevó a los bolcheviques al poder en Rusia?", "a": "La Revolución de Octubre", "cat": "historia", "dif": "medio", "sabias": "Se llama «de Octubre» por el calendario juliano; en el gregoriano ocurrió en noviembre."},
  {"n": 55, "q": "¿Qué emperador bizantino mandó recopilar el Corpus Iuris Civilis?", "a": "Justiniano I", "cat": "historia", "dif": "dificil", "sabias": "Durante la revuelta Niká de 532, Teodora habría convencido a Justiniano de no huir de la capital.", "lz": "A"},
  {"n": 87, "q": "¿Qué mar separa la península arábiga de África?", "a": "El mar Rojo", "cat": "geografia", "dif": "medio", "lz": "B", "par": [383], "sabias": "Su nombre se atribuye a las floraciones estacionales de algas rojizas."},
  {"n": 88, "q": "¿Qué cordillera rusa marca tradicionalmente el límite oriental de Europa?", "a": "Los montes Urales", "cat": "geografia", "dif": "medio", "sabias": "Se extienden unos 2.500 km de norte a sur, pero apenas superan los 1.800 m: son montañas muy antiguas y desgastadas.", "lz": "B"},
  {"n": 89, "q": "¿Cuál es la isla más grande del mundo, sin contar los continentes?", "a": "Groenlandia", "cat": "geografia", "dif": "medio", "sabias": "Pese a su nombre, «tierra verde», cuatro quintas partes de la isla están bajo el hielo.", "lz": "A"},
  {"n": 92, "q": "¿Qué lago se encuentra entre Perú y Bolivia y es considerado el lago navegable más alto del mundo?", "a": "El lago Titicaca", "cat": "geografia", "dif": "medio", "sabias": "Está a unos 3.800 m de altitud, más alto que cualquier cima de los Pirineos.", "lz": "A"},
  {"n": 93, "q": "¿Cuál es la montaña más alta de África, con una cumbre situada a unos 5.895 metros sobre el nivel del mar?", "a": "El Kilimanjaro", "cat": "geografia", "dif": "medio", "sabias": "Es un volcán dormido y la montaña aislada más alta del mundo: se alza sola sobre la llanura.", "alias": ["Monte Kilimanjaro"], "lz": "A"},
  {"n": 94, "q": "¿Qué desierto se extiende por gran parte del norte de Chile?", "a": "El desierto de Atacama", "cat": "geografia", "dif": "medio", "lz": "A", "sabias": "Es el desierto no polar más árido del mundo: hay zonas donde casi nunca llueve."},
  {"n": 95, "q": "¿Qué país alberga la región de Transilvania?", "a": "Rumanía", "cat": "geografia", "dif": "medio", "sabias": "Stoker nunca visitó Transilvania: escribió «Drácula» (1897) a partir de libros consultados en bibliotecas británicas.", "lz": "A"},
  {"n": 96, "q": "¿Cómo se llama la depresión oceánica más profunda conocida, situada en el océano Pacífico?", "a": "La fosa de las Marianas", "cat": "geografia", "dif": "medio", "sabias": "El Everest cabría entero dentro de la fosa y aún le sobrarían más de 2 km de agua.", "lz": "A"},
  {"n": 97, "q": "¿Qué lago ruso guarda una quinta parte del agua dulce líquida del planeta?", "a": "El lago Baikal", "cat": "geografia", "dif": "medio", "sabias": "Contiene más agua que todos los Grandes Lagos juntos.", "lz": "A"},
  {"n": 98, "q": "¿Qué río forma gran parte de la frontera entre México y Estados Unidos?", "a": "El río Bravo o río Grande", "cat": "geografia", "dif": "medio", "sabias": "Nace en las Rocosas de Colorado y en años secos se agota antes de desembocar.", "alias": ["Río Bravo del Norte", "Río Bravo", "Río Grande", "Bravo", "Rio Grande"], "lz": "A"},
  {"n": 99, "q": "¿Qué navegante portugués fue el primero en doblar el cabo de Buena Esperanza?", "a": "Bartolomé Díaz", "cat": "geografia", "dif": "medio", "sabias": "Lo bautizó «cabo de las Tormentas»; el rey lo rebautizó «Buena Esperanza».", "lz": "A", "alias": ["Bartolomeu Dias", "Bartolomé Dias", "Díaz", "Dias"]},
  {"n": 100, "q": "¿Qué mar de Oriente Medio marca el punto más bajo de la Tierra firme?", "a": "El mar Muerto", "cat": "geografia", "dif": "medio", "sabias": "Es casi diez veces más salado que el océano: ningún pez sobrevive en él y el cuerpo flota sin esfuerzo.", "lz": "B"},
  {"n": 101, "q": "¿Qué país está dividido entre Europa y Asia por el estrecho del Bósforo?", "a": "Turquía", "cat": "geografia", "dif": "medio", "lz": "B", "sabias": "Solo un 3 % de su territorio queda en la parte europea; el resto es la península de Anatolia.", "par": [382]},
  {"n": 102, "q": "¿Cuál es el mayor mar cerrado del mundo, entre Europa oriental y Asia?", "a": "El mar Caspio", "cat": "geografia", "dif": "medio", "lz": "A", "sabias": "Es el mayor lago del mundo, aunque se le llame «mar».", "par": [381]},
  {"n": 103, "q": "¿Qué canal artificial une el Atlántico y el Pacífico a través de América Central?", "a": "El canal de Panamá", "cat": "geografia", "dif": "medio", "sabias": "Se abrió en 1914 y ahorró a los barcos el largo rodeo por el cabo de Hornos, en el extremo sur de América.", "lz": "B"},
  {"n": 104, "q": "¿Qué país mide su progreso con el índice de «Felicidad Nacional Bruta»?", "a": "Bután", "cat": "geografia", "dif": "medio", "sabias": "Su constitución obliga a mantener al menos el 60 % del territorio cubierto de bosque.", "lz": "B"},
  {"n": 105, "q": "¿Qué estrecho separa Asia de América del Norte?", "a": "El estrecho de Bering", "cat": "geografia", "dif": "medio", "sabias": "Hace unos 20.000 años el mar estaba más bajo y se podía cruzar a pie por Beringia.", "lz": "A"},
  {"n": 106, "q": "¿Cuál es el único país del mundo cuya bandera nacional no tiene forma rectangular ni cuadrada?", "a": "Nepal", "cat": "geografia", "dif": "dificil", "sabias": "Sus dos triángulos representan, según una interpretación tradicional, las montañas del Himalaya.", "lz": "A"},
  {"n": 141, "q": "¿Qué factor astronómico es la causa principal de las estaciones del año?", "a": "La inclinación del eje terrestre", "cat": "ciencia", "dif": "medio", "sabias": "La Tierra está más cerca del Sol en enero, en pleno invierno del hemisferio norte.", "lz": "B"},
  {"n": 142, "q": "¿Cuál es aproximadamente la velocidad de la luz en el vacío?", "a": "300.000 km/s", "cat": "ciencia", "dif": "medio", "sabias": "La luz del Sol tarda unos 8 minutos en llegar a la Tierra.", "alias": ["300000", "300000 km/s", "300.000 kilómetros por segundo", "299.792 km/s"], "lz": "B"},
  {"n": 143, "q": "¿Cómo se llama el cambio directo de estado de sólido a gas?", "a": "Sublimación", "cat": "ciencia", "dif": "medio", "sabias": "El hielo seco es CO2 sólido y sublima a -78,5 °C; la nieve también puede desaparecer así en días fríos y secos.", "lz": "A"},
  {"n": 144, "q": "¿En qué orgánulos de las células vegetales tiene lugar principalmente la fotosíntesis?", "a": "Los cloroplastos", "cat": "ciencia", "dif": "medio", "sabias": "Se cree que fueron bacterias fotosintéticas que una célula «se tragó» hace más de mil millones de años.", "lz": "A"},
  {"n": 145, "q": "¿Qué parte del cerebro participa especialmente en el equilibrio y la coordinación motora?", "a": "El cerebelo", "cat": "ciencia", "dif": "medio", "lz": "A", "sabias": "Su nombre significa «cerebro pequeño», pero contiene más de la mitad de las neuronas del cerebro."},
  {"n": 146, "q": "¿Qué glándula del cuello produce la tiroxina, hormona clave del metabolismo?", "a": "La glándula tiroides", "cat": "ciencia", "dif": "medio", "lz": "A", "alias": ["Tiroides", "La tiroides"], "sabias": "Está situada delante de la tráquea y necesita yodo para fabricar sus hormonas."},
  {"n": 147, "q": "¿Qué unidad del Sistema Internacional se utiliza para medir la frecuencia?", "a": "El hercio", "cat": "ciencia", "dif": "medio", "sabias": "Una emisora de FM en el 100 del dial oscila cien millones de veces por segundo: 100 MHz.", "alias": ["Hz", "Hertz", "Hercios"], "lz": "B"},
  {"n": 148, "q": "¿Qué grupo sanguíneo es el donante universal de glóbulos rojos?", "a": "O negativo", "cat": "ciencia", "dif": "medio", "lz": "B", "sabias": "Se usa en urgencias cuando no se conoce el grupo sanguíneo del paciente.", "alias": ["O-", "O−", "O neg"]},
  {"n": 149, "q": "¿Qué tipo de energía está asociada al movimiento de un cuerpo?", "a": "Energía cinética", "cat": "ciencia", "dif": "medio", "sabias": "Si duplicas la velocidad, la energía cinética se cuadruplica.", "lz": "A"},
  {"n": 150, "q": "¿Qué tipo de enlace químico se forma habitualmente cuando un átomo transfiere electrones a otro?", "a": "Enlace iónico", "cat": "ciencia", "dif": "medio", "sabias": "La sal común, compuesto iónico, no funde hasta los 801 °C; por eso nunca se derrite al cocinar.", "lz": "A"},
  {"n": 151, "q": "¿Qué orgánulo celular actúa como la central energética de la célula?", "a": "La mitocondria", "cat": "ciencia", "dif": "medio", "sabias": "El ADN mitocondrial se hereda, por lo general, de la madre.", "lz": "A"},
  {"n": 152, "q": "¿En qué unidad se expresa la intensidad de corriente?", "a": "El amperio", "cat": "ciencia", "dif": "medio", "alias": ["Ampere"], "lz": "B", "sabias": "Unos 0,1 A atravesando el corazón pueden matar: lo peligroso es la corriente, no el voltaje."},
  {"n": 153, "q": "¿Qué fenómeno óptico hace que un objeto parezca desplazado cuando se observa a través del agua?", "a": "La refracción", "cat": "ciencia", "dif": "medio", "sabias": "En el agua la luz viaja a unos 225.000 km/s, un 25 % más lenta que en el vacío; por eso se desvía.", "alias": ["Refracción de la luz"], "lz": "A"},
  {"n": 154, "q": "¿Cómo se llama la explosión con la que muere una estrella masiva?", "a": "Una supernova", "cat": "ciencia", "dif": "medio", "sabias": "Buena parte de los elementos pesados del universo se forjaron en estrellas que explotaron.", "alias": ["Explosión de supernova"], "lz": "A"},
  {"n": 155, "q": "¿Qué fenómeno físico explica principalmente por qué el cielo diurno se ve azul?", "a": "La dispersión de Rayleigh", "cat": "ciencia", "dif": "dificil", "sabias": "Al amanecer y al atardecer la luz atraviesa más atmósfera y predominan tonos rojizos y anaranjados.", "lz": "A"},
  {"n": 156, "q": "¿Qué astrónomo formuló las leyes que describen el movimiento de los planetas alrededor del Sol?", "a": "Johannes Kepler", "cat": "ciencia", "dif": "dificil", "sabias": "Sus leyes salieron de décadas de datos que Tycho Brahe midió a simple vista, sin telescopio.", "lz": "A"},
  {"n": 157, "q": "¿Qué parte del oído interno convierte el sonido en señales nerviosas?", "a": "La cóclea", "cat": "ciencia", "dif": "dificil", "sabias": "«Cóclea» procede del griego y alude a su forma de espiral, semejante a una concha.", "lz": "A"},
  {"n": 158, "q": "¿Qué científico formuló el principio de incertidumbre?", "a": "Werner Heisenberg", "cat": "ciencia", "dif": "dificil", "sabias": "No se debe a una limitación de los instrumentos, sino a una propiedad fundamental de la mecánica cuántica.", "lz": "A"},
  {"n": 159, "q": "¿Qué partícula elemental actúa como mediadora de la interacción electromagnética?", "a": "El fotón", "cat": "ciencia", "dif": "dificil", "sabias": "La palabra «fotón» se acuñó en 1926; antes, Einstein hablaba de «cuantos de luz».", "lz": "A"},
  {"n": 160, "q": "¿Qué isótopo del carbono sirve para datar restos orgánicos?", "a": "Carbono-14", "cat": "ciencia", "dif": "dificil", "sabias": "El método es especialmente útil para restos de hasta unos 50.000 años.", "alias": ["C-14", "C14"], "lz": "B"},
  {"n": 161, "q": "¿Qué ley de la termodinámica establece que la entropía de un sistema aislado no disminuye?", "a": "La segunda ley", "cat": "ciencia", "dif": "dificil", "sabias": "El físico Rudolf Clausius acuñó la palabra «entropía» en 1865, a partir del griego «tropé»: transformación."},
  {"n": 162, "q": "¿Cómo se llama el método que fecha rocas y minerales a partir de isótopos radiactivos?", "a": "La datación radiométrica", "cat": "ciencia", "dif": "dificil", "sabias": "Con este método se calculó que la Tierra tiene unos 4.500 millones de años."},
  {"n": 163, "q": "¿Qué proceso permite a la célula reciclar sus propios componentes dañados?", "a": "Autofagia", "cat": "ciencia", "dif": "dificil", "sabias": "Significa «comerse a uno mismo»; su estudio le valió el Nobel de Medicina de 2016 a Yoshinori Ohsumi.", "lz": "A"},
  {"n": 164, "q": "¿Qué científico ordenó los elementos por sus propiedades y dejó huecos para los aún desconocidos?", "a": "Dmitri Mendeléyev", "cat": "ciencia", "dif": "dificil", "sabias": "Algunas de sus predicciones coincidieron después con elementos como el galio y el germanio.", "lz": "A", "alias": ["Mendeléyev", "Mendeleev", "Mendeleiev"]},
  {"n": 165, "q": "¿Qué planeta tarda más en dar una vuelta sobre sí mismo?", "a": "Venus", "cat": "ciencia", "dif": "dificil", "sabias": "Venus completa su órbita en unos 225 días terrestres, pero tarda cerca de 243 en girar sobre su eje.", "lz": "A"},
  {"n": 192, "q": "¿Qué estilo arquitectónico medieval destaca por sus arcos apuntados, bóvedas de crucería y grandes vitrales?", "a": "El gótico", "cat": "arte_literatura", "dif": "medio", "sabias": "«Gótico» era un insulto renacentista: lo juzgaban un arte bárbaro, propio de los godos.", "alias": ["Estilo gótico", "Arquitectura gótica", "Arte gótico"], "lz": "A"},
  {"n": 193, "q": "¿Qué movimiento artístico, ligado a Monet, buscaba captar los efectos cambiantes de la luz?", "a": "El impresionismo", "cat": "arte_literatura", "dif": "medio", "sabias": "El nombre nació como burla de un crítico ante «Impresión, sol naciente», de Monet.", "lz": "A"},
  {"n": 194, "q": "¿Quién escribió Moby-Dick?", "a": "Herman Melville", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "Se publicó en 1851 y no tuvo éxito en vida de su autor."},
  {"n": 195, "q": "¿Qué filósofo griego defendió la teoría de las Ideas o Formas, realidades eternas e inmutables?", "a": "Platón", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "Platón fundó la Academia de Atenas hacia el 387 a. C.; se considera un antecedente de la universidad."},
  {"n": 196, "q": "¿Qué conjunto monumental de Granada es famoso por el Patio de los Leones?", "a": "La Alhambra", "cat": "arte_literatura", "dif": "medio", "sabias": "Su nombre viene del árabe «al-Hamra», «la roja»; se atribuye al color rojizo de los muros de tapial del castillo.", "alias": ["Alhambra de Granada"], "lz": "B", "par": [205]},
  {"n": 198, "q": "¿Qué pintor renacentista italiano realizó La escuela de Atenas?", "a": "Rafael", "cat": "arte_literatura", "dif": "medio", "alias": ["Raphael"], "lz": "B", "sabias": "Se retrató a sí mismo mirando al espectador, con boina negra, en el borde derecho de la obra."},
  {"n": 199, "q": "¿Qué escritor colombiano ganó el Premio Nobel de Literatura en 1982 y escribió Cien años de soledad?", "a": "Gabriel García Márquez", "cat": "arte_literatura", "dif": "medio", "sabias": "Nació en Aracataca, el pueblo que inspiró el Macondo de la novela.", "lz": "A"},
  {"n": 200, "q": "¿Qué famoso dramaturgo y poeta español del Siglo de Oro escribió Fuenteovejuna?", "a": "Lope de Vega", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "Se le atribuyen más de 1.500 comedias, aunque solo se conserva una parte de ellas."},
  {"n": 201, "q": "¿Qué novela de Umberto Eco mezcla asesinatos y una abadía medieval?", "a": "El nombre de la rosa", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "Se publicó en 1980; Sean Connery protagonizó la adaptación de 1986."},
  {"n": 202, "q": "¿Qué escritora británica creó a Miss Marple y a Hercule Poirot?", "a": "Agatha Christie", "cat": "arte_literatura", "dif": "medio", "sabias": "Su obra «La ratonera» se estrenó en Londres en 1952 y es la obra de teatro que más tiempo lleva en cartel.", "lz": "A"},
  {"n": 203, "q": "¿Qué novela de Mary Shelley, de 1818, es la madre de la ciencia ficción?", "a": "Frankenstein", "cat": "arte_literatura", "dif": "dificil", "sabias": "Nació de un reto entre amigos para escribir historias de terror, en el verano frío de 1816.", "lz": "A"},
  {"n": 204, "q": "¿Qué movimiento literario de finales del siglo XIX se rebeló contra el realismo para buscar lo misterioso y lo subjetivo?", "a": "El simbolismo", "cat": "arte_literatura", "dif": "dificil", "sabias": "El poeta Jean Moréas publicó su manifiesto en Le Figaro en 1886; Verlaine y Mallarmé están entre sus referentes.", "lz": "B"},
  {"n": 205, "q": "¿Qué dinastía gobernó el reino de Granada hasta 1492?", "a": "Los nazaríes", "cat": "historia", "dif": "dificil", "sabias": "Su último sultán, Boabdil, entregó Granada en 1492 y, según la leyenda, lloró al marcharse.", "alias": ["Dinastía nazarí", "Reino nazarí"], "lz": "B", "par": [196]},
  {"n": 206, "q": "¿Qué movimiento artístico descompuso el mundo en formas geométricas y varios puntos de vista?", "a": "El cubismo", "cat": "arte_literatura", "dif": "dificil", "sabias": "Picasso y Braque lo desarrollaron juntos, casi como cómplices, entre 1908 y 1914.", "lz": "A"},
  {"n": 216, "q": "¿Quién compuso Las cuatro estaciones?", "a": "Antonio Vivaldi", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "Cada concierto va acompañado de un soneto que describe la estación."},
  {"n": 217, "q": "¿Qué director dirigió El resplandor y La naranja mecánica?", "a": "Stanley Kubrick", "cat": "arte_literatura", "dif": "medio", "sabias": "Hizo repetir 127 veces la escena de Wendy con el bate, récord de tomas en una escena con diálogo según el Guinness.", "lz": "A"},
  {"n": 218, "q": "¿Qué género de cine, de detectives y ambientes oscuros, triunfó en Hollywood en los años 40 y 50?", "a": "Cine negro", "cat": "arte_literatura", "dif": "medio", "alias": ["Film noir"], "lz": "B", "sabias": "«Film noir» lo acuñaron críticos franceses en 1946."},
  {"n": 219, "q": "¿Qué compositor austriaco es autor de óperas como Las bodas de Fígaro, Don Giovanni y La flauta mágica?", "a": "Wolfgang Amadeus Mozart", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "A los seis años, en 1762, tocó ante la emperatriz María Teresa en Viena."},
  {"n": 220, "q": "¿Qué compositor barroco compuso el famoso oratorio El Mesías, que incluye el conocido coro «Aleluya»?", "a": "Georg Friedrich Händel", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "Por tradición, el público se pone en pie al sonar el «Aleluya».", "alias": ["Händel", "Handel", "Haendel"]},
  {"n": 221, "q": "¿Qué compositor italiano escribió la ópera La traviata?", "a": "Giuseppe Verdi", "cat": "arte_literatura", "dif": "medio", "sabias": "Verdi la basó en «La dama de las camelias», novela de Alexandre Dumas hijo, y se estrenó en 1853.", "lz": "A"},
  {"n": 222, "q": "¿Qué compositor escribió la música de la película El bueno, el feo y el malo?", "a": "Ennio Morricone", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "Compuso música para más de 400 películas y series."},
  {"n": 223, "q": "Según los datos de la UNESCO de 2015, ¿qué país produjo más largometrajes?", "a": "India", "cat": "arte_literatura", "dif": "medio", "lz": "B", "sabias": "«Bollywood» une Bombay y Hollywood, pero allí se hace cine en más de veinte lenguas, no solo en hindi."},
  {"n": 224, "q": "¿Qué cantante estadounidense fue conocida como la «Reina del Soul»?", "a": "Aretha Franklin", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "Fue la primera mujer incluida en el Salón de la Fama del Rock and Roll, en 1987."},
  {"n": 225, "q": "¿Qué cantante británica lanzó el álbum «Back to Black» en 2006?", "a": "Amy Winehouse", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "En 2008 ganó cinco Grammy y los recogió por satélite desde Londres, porque no le concedieron el visado para viajar a EE. UU."},
  {"n": 226, "q": "¿Qué película de 1999, dirigida por las hermanas Wachowski, popularizó el efecto «bullet time»?", "a": "Matrix", "cat": "arte_literatura", "dif": "medio", "sabias": "Se rodó con un anillo de cámaras fijas dispuestas alrededor de los actores.", "alias": ["The Matrix"], "lz": "B"},
  {"n": 227, "q": "¿Qué película de Orson Welles (1941) empieza con la palabra «Rosebud»?", "a": "Ciudadano Kane", "cat": "arte_literatura", "dif": "dificil", "sabias": "Orson Welles tenía 25 años cuando la dirigió, protagonizó y coescribió.", "alias": ["Citizen Kane"], "lz": "A"},
  {"n": 234, "q": "¿Qué prueba de atletismo combina siete disciplinas diferentes?", "a": "Heptatlón", "cat": "deporte", "dif": "medio", "sabias": "Se disputa en dos jornadas, con cuatro pruebas el primer día y tres el segundo.", "lz": "A"},
  {"n": 235, "q": "¿Qué gran vuelta ciclista tiene el maillot rosa de líder?", "a": "Giro de Italia", "cat": "deporte", "dif": "medio", "sabias": "La maglia rosa imita el color rosa de las páginas del diario que organizó la carrera, La Gazzetta dello Sport.", "lz": "B"},
  {"n": 236, "q": "¿Qué nadador estadounidense consiguió ocho medallas de oro en los Juegos Olímpicos de Pekín 2008?", "a": "Michael Phelps", "cat": "deporte", "dif": "medio", "sabias": "Con ocho oros superó los siete que Mark Spitz había logrado en Múnich 1972, un récord que duró 36 años.", "lz": "A"},
  {"n": 237, "q": "¿Qué tenista masculino estableció el récord de 14 títulos individuales en Roland Garros?", "a": "Rafael Nadal", "cat": "deporte", "dif": "medio", "sabias": "Los ganó entre 2005 y 2022 y solo perdió cuatro partidos en toda su historia en París.", "lz": "A"},
  {"n": 238, "q": "¿En qué deporte se disputa la Ryder Cup?", "a": "Golf", "cat": "deporte", "dif": "medio", "lz": "B", "sabias": "Se disputa cada dos años y el trofeo lleva el nombre del empresario inglés Samuel Ryder."},
  {"n": 239, "q": "¿Qué país ganó el primer Mundial de fútbol en 1930?", "a": "Uruguay", "cat": "deporte", "dif": "medio", "sabias": "Fue anfitrión y campeón del primer Mundial, en 1930, tras vencer a Argentina en la final por 4-2.", "lz": "A"},
  {"n": 240, "q": "¿En qué deporte se utiliza un puck o disco?", "a": "Hockey sobre hielo", "cat": "deporte", "dif": "medio", "lz": "B", "sabias": "Un disco golpeado con fuerza puede superar los 160 km/h."},
  {"n": 241, "q": "¿Qué piloto de Fórmula 1 fue conocido por el apodo de El Kaiser?", "a": "Michael Schumacher", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Ganó siete títulos mundiales, cinco de ellos seguidos con Ferrari."},
  {"n": 242, "q": "¿Qué ciudad sudamericana acogió por primera vez unos Juegos Olímpicos de verano, en 2016?", "a": "Río de Janeiro", "cat": "deporte", "dif": "medio", "lz": "B", "alias": ["Rio de Janeiro", "Río", "Rio"], "sabias": "El Maracaná acogió las ceremonias de apertura y de clausura."},
  {"n": 243, "q": "¿Qué atleta jamaicano es famoso por sus récords mundiales en 100 y 200 metros?", "a": "Usain Bolt", "cat": "deporte", "dif": "medio", "sabias": "En el Mundial de Berlín 2009 corrió los 100 m en 9,58 s y los 200 m en 19,19 s, marcas que nadie había logrado antes.", "lz": "B"},
  {"n": 244, "q": "¿Qué jugador es famoso por sus triples y fue MVP de la NBA en 2015 y 2016?", "a": "Stephen Curry", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Curry recibió todos los votos para el MVP de la NBA en 2016, algo inédito hasta entonces."},
  {"n": 245, "q": "¿Qué boxeador filipino ganó títulos mundiales en ocho categorías de peso?", "a": "Manny Pacquiao", "cat": "deporte", "dif": "medio", "alias": ["Pacquiao", "Manny Pacquiao"], "lz": "B", "sabias": "Fue campeón desde el peso mosca (unos 51 kg) hasta el superwelter (unos 70 kg): casi veinte kilos entre su primer y su último título."},
  {"n": 246, "q": "¿Qué ciclista estadounidense fue despojado de sus siete títulos del Tour de Francia por dopaje?", "a": "Lance Armstrong", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Los siete Tours quedaron sin ganador: la organización decidió no reasignarlos a ningún otro ciclista."},
  {"n": 247, "q": "¿Qué selección ha ganado más títulos del Mundial de rugby masculino?", "a": "Sudáfrica", "cat": "deporte", "dif": "medio", "alias": ["Springboks"], "lz": "A", "sabias": "Suma cuatro títulos (1995, 2007, 2019 y 2023): más que ninguna otra selección."},
  {"n": 248, "q": "¿Qué ciclista español ganó cinco Tours de Francia consecutivos entre 1991 y 1995?", "a": "Miguel Induráin", "cat": "deporte", "dif": "medio", "sabias": "Se dijo que su corazón en reposo latía unas 28 veces por minuto.", "lz": "A"},
  {"n": 249, "q": "¿Qué boxeador fue campeón mundial de los pesos pesados con 20 años, el más joven de la historia?", "a": "Mike Tyson", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Noqueó a Trevor Berbick en el segundo asalto, el 22 de noviembre de 1986, en Las Vegas."},
  {"n": 250, "q": "¿Qué piloto brasileño, tricampeón de F1, murió en Imola en 1994?", "a": "Ayrton Senna", "cat": "deporte", "dif": "dificil", "sabias": "Murió en la curva de Tamburello, que al año siguiente se transformó en una chicane.", "lz": "A"},
  {"n": 261, "q": "¿Qué empresa adquirió Android Inc. en 2005 y posteriormente impulsó el sistema operativo Android?", "a": "Google", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "Se cree que la compra costó unos 50 millones de dólares."},
  {"n": 262, "q": "¿Qué dispositivo dirige el tráfico de una red local hacia Internet?", "a": "Un router (enrutador)", "cat": "cultura_general", "dif": "medio", "sabias": "Los primeros, de 1969, fueron los IMP: ordenadores del tamaño de un frigorífico que conectaban las primeras redes.", "lz": "B", "alias": ["Router", "Enrutador", "Un enrutador"]},
  {"n": 263, "q": "¿Qué lenguaje de programación domina en análisis de datos e inteligencia artificial?", "a": "Python", "cat": "cultura_general", "dif": "medio", "sabias": "Su nombre rinde homenaje al grupo cómico Monty Python, no a la serpiente."},
  {"n": 264, "q": "¿Cómo se llama el fraude que roba datos personales con mensajes o webs falsos que imitan a una entidad real?", "a": "Phishing", "cat": "cultura_general", "dif": "medio", "sabias": "Suena igual que fishing, «pescar»: los estafadores lanzan el cebo y esperan a que alguien pique.", "lz": "A"},
  {"n": 265, "q": "¿Qué lenguaje se utiliza principalmente para estructurar el contenido de las páginas web?", "a": "HTML", "cat": "cultura_general", "dif": "medio", "sabias": "Tim Berners-Lee lo describió en 1991 con solo 18 etiquetas; hoy hay más de cien.", "lz": "A"},
  {"n": 266, "q": "¿Qué invento transmitió mensajes por señales eléctricas antes del teléfono?", "a": "El telégrafo", "cat": "cultura_general", "dif": "medio", "sabias": "Samuel Morse envió el primer mensaje público por telégrafo en 1844.", "alias": ["Telégrafo eléctrico"], "lz": "A"},
  {"n": 267, "q": "¿Qué nombre recibe la tecnología que permite pagar acercando una tarjeta o teléfono a un terminal compatible?", "a": "NFC", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "Significa «comunicación de campo cercano»; las etiquetas NFC no necesitan batería: se alimentan del campo del móvil."},
  {"n": 268, "q": "¿Qué unidad se utiliza para medir la velocidad de transmisión de datos en una red informática?", "a": "Bits por segundo (bit/s)", "cat": "cultura_general", "dif": "medio", "sabias": "Un byte son 8 bits: una conexión de 100 Mbit/s descarga, como máximo, unos 12,5 megabytes por segundo.", "alias": ["Bits por segundo", "bit/s", "bps"]},
  {"n": 269, "q": "¿Qué protocolo traduce nombres de dominio, como www.ejemplo.com, en direcciones IP?", "a": "DNS", "cat": "cultura_general", "dif": "medio", "alias": ["Protocolo DNS"], "lz": "A", "sabias": "Es la agenda de contactos de la red: tú recuerdas nombres, él guarda los números."},
  {"n": 270, "q": "¿Qué componente de un teléfono detecta principalmente los movimientos de rotación del dispositivo?", "a": "El giroscopio", "cat": "cultura_general", "dif": "medio", "sabias": "El nombre «giroscopio» lo acuñó Léon Foucault en 1852, al usar uno para demostrar que la Tierra gira.", "lz": "A"},
  {"n": 271, "q": "¿Qué misión espacial llevó por primera vez seres humanos a la superficie de la Luna?", "a": "Apolo 11", "cat": "cultura_general", "dif": "medio", "sabias": "El módulo se llamaba Eagle; Michael Collins esperó en órbita y fue el único de la tripulación que no pisó la Luna.", "alias": ["Apolo XI"], "lz": "B"},
  {"n": 272, "q": "¿Qué red mundial conecta miles de millones de dispositivos mediante TCP/IP?", "a": "Internet", "cat": "cultura_general", "dif": "medio", "sabias": "En 1971 Ray Tomlinson envió el primer correo entre ordenadores y eligió la arroba para separar usuario y máquina."},
  {"n": 273, "q": "¿Qué red del Pentágono, nacida en 1969, conectó los primeros ordenadores entre universidades?", "a": "ARPANET", "cat": "cultura_general", "dif": "dificil", "sabias": "El primer mensaje enviado por ARPANET en 1969 fue «LO», porque el sistema falló antes de completar «LOGIN».", "lz": "A"},
  {"n": 274, "q": "¿Qué nombre recibió el primer satélite artificial de la historia, lanzado por la Unión Soviética en 1957?", "a": "Sputnik 1", "cat": "cultura_general", "dif": "dificil", "sabias": "Su señal de radio, un «bip-bip», podía captarse con aparatos de aficionado.", "alias": ["Sputnik"], "lz": "B"},
  {"n": 289, "q": "¿Qué organización internacional tiene su sede principal en Nueva York y fue fundada en 1945?", "a": "La ONU", "cat": "cultura_general", "dif": "medio", "alias": ["Naciones Unidas"], "lz": "B", "sabias": "Su sede se levantó en unos terrenos comprados con una donación de John D. Rockefeller Jr."},
  {"n": 290, "q": "¿Qué metal precioso tiene el símbolo químico Ag?", "a": "La plata", "cat": "ciencia", "dif": "medio", "sabias": "Su símbolo, Ag, viene del latín argentum, de donde procede también el nombre de Argentina.", "lz": "B"},
  {"n": 291, "q": "¿Cuál es la lengua individual con mayor número de hablantes nativos del mundo?", "a": "El chino mandarín", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "Tiene cuatro tonos: «ma» puede significar madre, cáñamo, caballo o regañar según la entonación."},
  {"n": 292, "q": "¿Qué indicador mide el valor de lo que produce un país en un año?", "a": "El Producto Interior Bruto (PIB)", "cat": "cultura_general", "dif": "medio", "sabias": "Simon Kuznets lo diseñó en los años treinta y ya advirtió de que no servía para medir el bienestar de un país.", "alias": ["Producto Interno Bruto", "PIB", "El PIB", "Producto Interior Bruto"], "lz": "B"},
  {"n": 293, "q": "¿Qué filósofo griego fue maestro de Alejandro Magno?", "a": "Aristóteles", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "Fue su tutor desde que Alejandro tenía unos 13 años."},
  {"n": 294, "q": "¿Qué rama de la lingüística estudia el origen y la historia de las palabras?", "a": "La etimología", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "Viene del griego «etymos», «verdadero», y «logos», «estudio»."},
  {"n": 295, "q": "¿Qué continente tiene actualmente el mayor número de Estados soberanos?", "a": "África", "cat": "geografia", "dif": "medio", "sabias": "África tiene 54 países reconocidos por la ONU, más que ningún otro continente.", "lz": "B", "par": [297]},
  {"n": 296, "q": "¿Qué país fue el primero en conceder a las mujeres el derecho al voto en elecciones nacionales?", "a": "Nueva Zelanda", "cat": "historia", "dif": "medio", "sabias": "El voto femenino llegó allí en 1893, casi tres décadas antes que en EE. UU.", "lz": "A", "par": [338]},
  {"n": 297, "q": "¿Qué continente atraviesan a la vez el ecuador y el meridiano de Greenwich?", "a": "África", "cat": "geografia", "dif": "medio", "lz": "B", "par": [295], "sabias": "El punto exacto donde se cruzan, a 0° de latitud y 0° de longitud, cae en el golfo de Guinea, en pleno mar."},
  {"n": 298, "q": "¿Quién patentó el teléfono en 1876?", "a": "Alexander Graham Bell", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "La primera frase por teléfono fue de Bell a su ayudante: «Señor Watson, venga, le necesito»."},
  {"n": 299, "q": "¿Qué país regaló a Estados Unidos la Estatua de la Libertad?", "a": "Francia", "cat": "cultura_general", "dif": "medio", "sabias": "Fue un regalo de 1886 y su estructura interior de hierro la diseñó Gustave Eiffel.", "lz": "B"},
  {"n": 300, "q": "¿Quién inició la primera vuelta al mundo que acabó Elcano?", "a": "Fernando de Magallanes", "cat": "historia", "dif": "medio", "sabias": "Murió en Mactán, en Filipinas, en 1521, luchando contra el jefe local Lapulapu, hoy héroe nacional filipino.", "lz": "A"},
  {"n": 301, "q": "¿Qué batalla naval de 1571 frenó a los otomanos en el Mediterráneo?", "a": "La batalla de Lepanto", "cat": "historia", "dif": "dificil", "sabias": "Cervantes combatió allí y perdió el uso de la mano izquierda: de ahí lo de «el manco de Lepanto».", "lz": "A"},
  {"n": 302, "q": "¿Qué emperador romano concedió en el año 212 la ciudadanía a casi todos los hombres libres del Imperio?", "a": "Caracalla", "cat": "historia", "dif": "dificil", "sabias": "Según el historiador Dion Casio, buscaba aumentar la recaudación de impuestos.", "alias": ["Emperador Caracalla"], "lz": "A"},
  {"n": 303, "q": "¿Qué líder unificó las tribus mongolas y fundó en 1206 el Imperio mongol?", "a": "Gengis Kan", "cat": "historia", "dif": "medio", "sabias": "Nació con el nombre de Temüjin y recibió su título en 1206, al ser proclamado jefe de todos los mongoles.", "alias": ["Genghis Khan", "Gengis Khan"], "lz": "A"},
  {"n": 304, "q": "¿Qué país contiene el salar de Uyuni, la mayor planicie salina continua del mundo?", "a": "Bolivia", "cat": "geografia", "dif": "dificil", "sabias": "En la estación húmeda se convierte en un espejo gigante.", "lz": "A"},
  {"n": 305, "q": "¿Qué efecto hace que un reloj en movimiento marche más lento, según la relatividad especial?", "a": "La dilatación temporal", "cat": "ciencia", "dif": "dificil", "alias": ["Dilatación del tiempo"], "lz": "B", "sabias": "En el GPS se compensa junto con la relatividad general; sin ambas correcciones, se desviaría unos 10 km al día."},
  {"n": 306, "q": "¿Qué estructura del ADN propusieron Watson y Crick en 1953?", "a": "La doble hélice", "cat": "ciencia", "dif": "dificil", "sabias": "Los datos de rayos X de Rosalind Franklin fueron clave para descubrirla.", "lz": "B"},
  {"n": 307, "q": "¿En qué tragedia isabelina aparecen Rosencrantz y Guildenstern?", "a": "Hamlet", "cat": "arte_literatura", "dif": "dificil", "sabias": "Tom Stoppard les dedicó en 1966 una obra propia, «Rosencrantz y Guildenstern han muerto», que cuenta la historia desde su punto de vista.", "lz": "A"},
  {"n": 308, "q": "¿Cuál es la única lengua semítica oficial de la Unión Europea?", "a": "El maltés", "cat": "cultura_general", "dif": "dificil", "sabias": "Es una mezcla singular: base árabe con muchísimas palabras del italiano y del inglés.", "alias": ["Idioma maltés", "Lengua maltesa"], "lz": "A"},
  {"n": 309, "q": "¿Qué empresa creó el lenguaje de programación Java originalmente bajo el proyecto Green?", "a": "Sun Microsystems", "cat": "cultura_general", "dif": "dificil", "sabias": "Se llamó Oak, «roble», por un árbol que había frente al despacho de su creador.", "lz": "A"},
  {"n": 310, "q": "¿Qué tenista logró el Golden Slam: los cuatro Grand Slam y el oro olímpico en un año?", "a": "Steffi Graf", "cat": "deporte", "dif": "dificil", "sabias": "Su oro llegó en Seúl 1988, cuando el tenis volvía a los Juegos tras 64 años de ausencia.", "lz": "A"},
  {"n": 311, "q": "¿Qué país cuenta con más islas del mundo, según los recuentos oficiales?", "a": "Suecia", "cat": "geografia", "dif": "dificil", "sabias": "Statistics Sweden contó 267.570 islas en 2013; el total depende del tamaño mínimo que se exija para llamar «isla» a un trozo de tierra."},
  {"n": 312, "q": "¿Qué estructura cerebral desempeña un papel fundamental en la consolidación de nuevos recuerdos?", "a": "Hipocampo", "cat": "ciencia", "dif": "dificil", "sabias": "Su nombre viene de su forma, que recuerda a un caballito de mar.", "lz": "A"},
  {"n": 313, "q": "¿Qué científico fue el primero en observar células utilizando un microscopio y acuñó el término «célula»?", "a": "Robert Hooke", "cat": "ciencia", "dif": "dificil", "sabias": "Las llamó «cellulae» por las celdas de los monjes; no veía células vivas, sino las paredes huecas del corcho.", "lz": "A"},
  {"n": 314, "q": "¿Qué proceso permite a las estrellas convertir hidrógeno en helio y brillar?", "a": "Fusión nuclear", "cat": "ciencia", "dif": "dificil", "sabias": "El Sol convierte cada segundo unos 600 millones de toneladas de hidrógeno en helio.", "lz": "A"},
  {"n": 315, "q": "¿Qué director japonés dirigió Los siete samuráis?", "a": "Akira Kurosawa", "cat": "arte_literatura", "dif": "dificil", "sabias": "Inspiró «Los siete magníficos», el western de 1960.", "lz": "A"},
  {"n": 316, "q": "¿Qué película ganó el primer Óscar a la mejor película en 1929?", "a": "Wings", "cat": "arte_literatura", "dif": "dificil", "sabias": "La ceremonia duró unos quince minutos y los ganadores se conocían desde tres meses antes."},
  {"n": 317, "q": "¿Qué protocolo de 1987 estableció la eliminación progresiva de sustancias que agotan la capa de ozono?", "a": "El Protocolo de Montreal", "cat": "cultura_general", "dif": "dificil", "sabias": "Es el primer tratado ratificado por todos los países miembros de Naciones Unidas; el agujero de ozono se va cerrando poco a poco.", "lz": "A"},
  {"n": 318, "q": "¿Qué guerra enfrentó de forma intermitente a Inglaterra y Francia desde 1337 por el trono francés?", "a": "La guerra de los Cien Años", "cat": "historia", "dif": "dificil", "sabias": "Duró 116 años, entre 1337 y 1453; en ella destacó Juana de Arco.", "lz": "A"},
  {"n": 319, "q": "¿Qué velocista y saltador estadounidense ganó nueve oros olímpicos entre 1984 y 1996?", "a": "Carl Lewis", "cat": "deporte", "dif": "dificil", "sabias": "Ganó el salto de longitud en cuatro Juegos seguidos, de 1984 a 1996.", "lz": "A"},
  {"n": 320, "q": "¿Qué institución fija la política monetaria de la zona euro?", "a": "Banco Central Europeo", "cat": "cultura_general", "dif": "dificil", "sabias": "El BCE se creó en 1998; el euro circuló como dinero virtual desde 1999 y en monedas y billetes desde 2002.", "alias": ["BCE"], "lz": "B"},
  {"n": 325, "q": "¿Qué país ganó la primera Copa Mundial de fútbol femenino de la FIFA, disputada en 1991?", "a": "Estados Unidos", "cat": "deporte", "dif": "medio", "sabias": "En aquella edición, los partidos duraban 80 minutos, diez menos que los 90 habituales en el fútbol masculino.", "alias": ["EEUU", "EE. UU.", "USA", "Estados Unidos de América"], "lz": "B"},
  {"n": 326, "q": "¿Qué tenista ganó cinco veces consecutivas el torneo de Wimbledon entre 1976 y 1980?", "a": "Björn Borg", "cat": "deporte", "dif": "medio", "sabias": "Se retiró en 1983, con solo 26 años y once Grand Slam: seis Roland Garros y cinco Wimbledon.", "lz": "A"},
  {"n": 327, "q": "¿Qué golfista estadounidense ganó cinco veces el Masters de Augusta?", "a": "Tiger Woods", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Lo ganó en 2019 tras once años sin ganar un grande."},
  {"n": 328, "q": "¿Qué piloto español ganó los Campeonatos del Mundo de Fórmula 1 de 2005 y 2006?", "a": "Fernando Alonso", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "En 2005 fue el campeón más joven de la historia de la F1 hasta entonces."},
  {"n": 329, "q": "¿Qué boxeador ganó el oro olímpico en 1960 antes de ser campeón mundial de los pesados?", "a": "Muhammad Ali", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Muhammad Ali todavía competía como Cassius Clay cuando ganó el oro olímpico en Roma 1960.", "alias": ["Cassius Clay", "Ali", "Cassius Marcellus Clay"]},
  {"n": 330, "q": "¿Qué español fue el primero en ganar un anillo de la NBA, con los Lakers en 2009?", "a": "Pau Gasol", "cat": "deporte", "dif": "medio", "lz": "A", "alias": ["Gasol", "Pau"], "sabias": "Pau Gasol ganó con los Lakers los títulos de 2009 y 2010, y su hermano Marc lo conseguiría en 2019 con los Raptors."},
  {"n": 331, "q": "¿Cuáles son las tres armas utilizadas en la esgrima olímpica?", "a": "Florete, espada y sable", "cat": "deporte", "dif": "medio", "sabias": "Se distinguen por dónde vale tocar: en el florete solo el tronco; en el sable, de la cintura para arriba; en la espada, todo el cuerpo.", "lz": "B"},
  {"n": 332, "q": "¿Qué deporte se juega deslizando piedras de granito sobre hielo mientras otros barren?", "a": "Curling", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Las piedras, de unos 19 kg, se tallan casi todas con el granito de una isla escocesa, Ailsa Craig."},
  {"n": 333, "q": "¿Qué atleta sudafricano fue el primer corredor con dos piernas amputadas en competir en unos Juegos Olímpicos?", "a": "Oscar Pistorius", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Sus prótesis de fibra de carbono se llaman «Cheetah» y le valieron el apodo de «Blade Runner»."},
  {"n": 334, "q": "¿Qué falta se pita en baloncesto por protestar, aunque no haya contacto?", "a": "Falta técnica", "cat": "deporte", "dif": "medio", "sabias": "Con dos técnicas en un mismo partido se expulsa al jugador.", "lz": "B"},
  {"n": 335, "q": "¿Cuántas vueltas a una pista de 400 m son los 1.500 m lisos?", "a": "3,75 vueltas", "cat": "deporte", "dif": "medio", "sabias": "Es la «milla de los europeos»: la milla anglosajona mide 1.609 m, unos 109 m más.", "alias": ["3,75", "3.75", "tres vueltas y tres cuartos"]},
  {"n": 336, "q": "¿Qué deporte «se practicó» en la Luna en 1971?", "a": "Golf", "cat": "deporte", "dif": "dificil", "sabias": "Alan Shepard golpeó dos bolas con un hierro 6 improvisado durante la misión Apolo 14.", "lz": "B"},
  {"n": 338, "q": "¿Qué tratado de 1840 entre la Corona británica y jefes maoríes es el documento fundacional de Nueva Zelanda?", "a": "Tratado de Waitangi", "cat": "historia", "dif": "medio", "sabias": "Las versiones inglesa y maorí no decían lo mismo, y eso aún genera debate.", "lz": "A", "par": [296]},
  {"n": 339, "q": "¿Qué reunión internacional de 1814-1815 redibujó el mapa de Europa tras la caída de Napoleón?", "a": "Congreso de Viena", "cat": "historia", "dif": "medio", "sabias": "Allí el diplomático Talleyrand logró que el país derrotado negociara como una potencia más.", "lz": "A", "par": [413]},
  {"n": 340, "q": "¿Cómo se llamó el régimen de segregación racial que rigió en Sudáfrica desde 1948?", "a": "Apartheid", "cat": "historia", "dif": "medio", "sabias": "La Ley de Registro de la Población, de 1950, clasificó a cada sudafricano por «raza» y fijó dónde podía vivir y trabajar.", "lz": "A"},
  {"n": 341, "q": "¿Qué ciudad italiana, hogar de los Médici, se considera la cuna del gran renacer artístico del siglo XV?", "a": "Florencia", "cat": "historia", "dif": "medio", "sabias": "Esos banqueros protegieron a artistas como Botticelli y Donatello.", "lz": "B", "alias": ["Florencia (Italia)"]},
  {"n": 342, "q": "¿Qué líder bolchevique fue el primer jefe de gobierno de la Rusia soviética?", "a": "Vladímir Lenin", "cat": "historia", "dif": "medio", "sabias": "Murió en 1924 y su sucesión la ganó Stalin tras una lucha de poder.", "lz": "B"},
  {"n": 346, "q": "¿Qué país africano tiene tres capitales oficiales?", "a": "Sudáfrica", "cat": "geografia", "dif": "medio", "sabias": "Pretoria gobierna, Ciudad del Cabo legisla y Bloemfontein juzga.", "lz": "A"},
  {"n": 347, "q": "¿Qué país europeo, conocido por su forma alargada a lo largo del mar Adriático, tiene su capital en Zagreb?", "a": "Croacia", "cat": "geografia", "dif": "medio", "lz": "B", "sabias": "Tiene más de mil islas, aunque solo unas 50 están habitadas."},
  {"n": 348, "q": "¿Cuál es el pico más alto de los Alpes, entre Francia e Italia?", "a": "El Mont Blanc", "cat": "geografia", "dif": "medio", "lz": "A", "sabias": "En 1786 dos franceses lo escalaron por primera vez y así nació el alpinismo."},
  {"n": 349, "q": "¿Cómo se llama la meseta más alta y extensa del mundo, conocida como «el techo del mundo»?", "a": "Meseta del Tíbet", "cat": "geografia", "dif": "dificil", "sabias": "Se la llama el «Tercer Polo»: tiene más hielo que cualquier otra región fuera del Ártico y la Antártida.", "alias": ["Altiplano del Tíbet", "Altiplano tibetano"], "lz": "B"},
  {"n": 350, "q": "¿Qué científico propuso en 1912 la teoría de la deriva continental?", "a": "Alfred Wegener", "cat": "ciencia", "dif": "medio", "sabias": "Su idea de los continentes a la deriva se rechazó durante décadas, hasta la tectónica de placas.", "lz": "A"},
  {"n": 351, "q": "¿Qué tipo de ARN transporta aminoácidos hasta el ribosoma durante la síntesis de proteínas?", "a": "ARN de transferencia", "cat": "ciencia", "dif": "medio", "sabias": "Tiene forma de trébol: en un extremo lleva el aminoácido y en el otro, el triplete que lee el código.", "alias": ["ARNt", "tRNA"], "lz": "B"},
  {"n": 352, "q": "¿Cómo se llaman los vasos que llevan la sangre desde el corazón al resto del cuerpo?", "a": "Arterias", "cat": "ciencia", "dif": "medio", "sabias": "Las arterias pulmonares son la excepción: llevan sangre pobre en oxígeno.", "lz": "B"},
  {"n": 353, "q": "¿Cómo se llama el proceso por el que los sedimentos se compactan hasta formar roca?", "a": "Litificación", "cat": "ciencia", "dif": "dificil", "sabias": "Las rocas sedimentarias cubren unas tres cuartas partes de la superficie de los continentes y en ellas aparecen casi todos los fósiles.", "alias": ["La litificación", "Diagénesis"]},
  {"n": 354, "q": "¿Qué fenómeno anula la resistencia eléctrica de un material a muy bajas temperaturas?", "a": "Superconductividad", "cat": "ciencia", "dif": "dificil", "sabias": "Se usa en los potentes imanes de las resonancias magnéticas.", "lz": "A"},
  {"n": 355, "q": "¿Qué civilización mesoamericana contó de 20 en 20 e inventó el cero por su cuenta?", "a": "Maya", "cat": "cultura_general", "dif": "medio", "sabias": "Su calendario combinaba un ciclo ritual de 260 días con uno solar de 365; ambos vuelven a coincidir cada 52 años.", "alias": ["Civilización maya"], "lz": "A"},
  {"n": 356, "q": "¿Qué código numérico identifica cada edición de un libro?", "a": "ISBN", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "El ISBN pasó de 10 a 13 dígitos para integrarse mejor en el sistema internacional de códigos de barras."},
  {"n": 357, "q": "¿Cómo se llama el sistema de lectura en relieve para personas ciegas?", "a": "Sistema Braille", "cat": "cultura_general", "dif": "medio", "sabias": "Louis Braille lo inventó con solo 15 años, en 1824, y era ciego desde la infancia.", "lz": "A"},
  {"n": 358, "q": "¿Qué premio de la Universidad de Columbia reconoce periodismo, literatura y música?", "a": "Los Premios Pulitzer", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "Se conceden desde 1917 y los creó el editor Joseph Pulitzer."},
  {"n": 359, "q": "¿Qué instrumento de teclado barroco, de cuerdas pulsadas con plectros, fue precursor del piano?", "a": "Clavecín", "cat": "arte_literatura", "dif": "medio", "sabias": "Bartolomeo Cristofori inventó el piano hacia 1700.", "alias": ["Clavicémbalo"], "lz": "B"},
  {"n": 360, "q": "¿Quién escribió la saga de novelas de Harry Potter?", "a": "J. K. Rowling", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "El primer libro se publicó en 1997, tras ser rechazado por varias editoriales.", "alias": ["JK Rowling", "J.K. Rowling", "Rowling"]},
  {"n": 363, "q": "¿En qué país se originó el taekwondo moderno?", "a": "Corea del Sur", "cat": "deporte", "dif": "medio", "sabias": "El taekwondo debutó como deporte olímpico oficial en Sídney 2000.", "lz": "A"},
  {"n": 366, "q": "¿Qué jugador anotó 100 puntos en un partido de la NBA, en 1962?", "a": "Wilt Chamberlain", "cat": "deporte", "dif": "dificil", "sabias": "Solo Kobe Bryant se ha acercado, con 81 puntos en 2006.", "lz": "B", "alias": ["Chamberlain", "Wilt"]},
  {"n": 370, "q": "En baloncesto, ¿de cuánto tiempo dispone un equipo para lanzar a canasta tras recuperar el balón?", "a": "24 segundos", "cat": "deporte", "dif": "medio", "sabias": "El límite se introdujo en 1954 para evitar partidos con muy pocos tiros.", "alias": ["24", "veinticuatro", "veinticuatro segundos"], "lz": "A"},
  {"n": 371, "q": "¿En qué deporte se disputa la America's Cup, el trofeo internacional más antiguo aún en juego?", "a": "Vela", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Su nombre viene de la goleta «America», que ganó la primera edición, en 1851.", "alias": ["La vela", "Regatas"]},
  {"n": 372, "q": "¿En qué país se inventó el juego del pádel a finales de la década de 1960?", "a": "México", "cat": "deporte", "dif": "medio", "sabias": "Enrique Corcuera creó la primera pista en Acapulco en 1969, en su propia casa.", "lz": "A"},
  {"n": 322, "q": "¿Qué atleta estadounidense ganó cuatro medallas de oro en los Juegos Olímpicos de Berlín de 1936?", "a": "Jesse Owens", "cat": "deporte", "dif": "facil", "sabias": "De vuelta en EE. UU., el presidente Roosevelt no lo invitó a la Casa Blanca.", "lz": "B"},
  {"n": 324, "q": "¿Cómo se denomina en golf completar un hoyo con un solo golpe desde la salida?", "a": "Hoyo en uno", "cat": "deporte", "dif": "facil", "lz": "B", "alias": ["Hole in one"], "sabias": "Se calcula que para un aficionado ocurre una vez cada 12.500 intentos, aproximadamente."},
  {"n": 364, "q": "¿Qué deporte combina esquí de fondo y tiro con rifle?", "a": "Biatlón", "cat": "deporte", "dif": "facil", "sabias": "Se dispara a 50 m: en posición tumbada la diana mide 4,5 cm, poco más que una pelota de pimpón.", "lz": "B"},
  {"n": 374, "q": "¿Qué gran río asiático atraviesa China y varios países del Sudeste Asiático?", "a": "Mekong", "cat": "geografia", "dif": "medio", "alias": ["Río Mekong"], "lz": "A", "sabias": "Su delta vietnamita, llamado «de los nueve dragones» por sus brazos, da cerca de la mitad del arroz del país."},
  {"n": 375, "q": "¿Cómo se denomina la extensa llanura fértil que ocupa gran parte del centro y este de Argentina?", "a": "Pampas", "cat": "geografia", "dif": "medio", "alias": ["Llanura pampeana"], "lz": "A", "sabias": "El ombú, árbol símbolo de la pampa, no es un árbol: es una planta herbácea gigante de tronco no leñoso."},
  {"n": 376, "q": "¿Cuál es la cordillera más larga del mundo en tierra firme?", "a": "Andes", "cat": "geografia", "dif": "medio", "sabias": "En ellos está el Ojos del Salado, el volcán más alto del mundo, en la frontera de Chile y Argentina, con 6.893 m.", "alias": ["Cordillera de los Andes"], "lz": "B"},
  {"n": 377, "q": "¿Cómo se denomina una línea de un mapa que une puntos de igual altitud?", "a": "Curva de nivel", "cat": "geografia", "dif": "medio", "sabias": "Cuanto más juntas están las líneas en el mapa, más empinada es la ladera.", "lz": "B", "alias": ["Curvas de nivel", "Isohipsa"]},
  {"n": 378, "q": "¿Cómo se denomina el proceso por el que aumenta la proporción de población que vive en ciudades?", "a": "Urbanización", "cat": "geografia", "dif": "medio", "lz": "B", "sabias": "Desde 2007, más de la mitad de la población mundial vive en ciudades."},
  {"n": 379, "q": "¿Cuál es la capital de Mongolia?", "a": "Ulán Bator", "cat": "geografia", "dif": "medio", "alias": ["Ulaanbaatar", "Ulan Bator"], "lz": "B", "sabias": "Por su altitud, latitud y lejanía del mar, Ulán Bator soporta inviernos extremos y suele figurar como la capital más fría del mundo."},
  {"n": 381, "q": "¿Cuál es el país sin salida al mar más extenso del mundo?", "a": "Kazajistán", "cat": "geografia", "dif": "dificil", "sabias": "Tiene costa en el Caspio, pero ese mar está cerrado: no llega a ningún océano.", "lz": "A", "par": [102]},
  {"n": 383, "q": "¿Qué canal artificial de navegación une el mar Rojo con el mar Mediterráneo a través de Egipto?", "a": "Canal de Suez", "cat": "geografia", "dif": "medio", "sabias": "Se inauguró en 1869 y acortó en semanas el viaje entre Europa y Asia.", "lz": "B", "par": [87]},
  {"n": 385, "q": "¿Cómo se denomina la relación ecológica en la que ambas especies obtienen un beneficio?", "a": "Mutualismo", "cat": "ciencia", "dif": "medio", "sabias": "Las hormigas cultivan hongos para alimentarse desde hace unos 50 millones de años, mucho antes de que existiera la agricultura humana.", "lz": "A", "alias": ["Simbiosis mutualista"]},
  {"n": 387, "q": "¿Qué sustancia envuelve los axones y acelera los impulsos nerviosos?", "a": "Mielina", "cat": "ciencia", "dif": "dificil", "alias": ["Vaina de mielina"], "lz": "A", "sabias": "La pérdida de mielina es lo que caracteriza a la esclerosis múltiple."},
  {"n": 388, "q": "¿Cómo se llama el proceso por el que un resto orgánico queda conservado en las rocas?", "a": "Fosilización", "cat": "ciencia", "dif": "medio", "sabias": "Los tejidos blandos rara vez fosilizan: por eso conocemos mucho mejor a los animales con huesos o conchas que a las medusas.", "lz": "B"},
  {"n": 389, "q": "¿Cómo se denominan las rocas formadas cuando el magma o la lava se enfrían y solidifican?", "a": "Ígneas", "cat": "ciencia", "dif": "medio", "sabias": "El granito se enfría despacio bajo tierra y forma cristales grandes; el basalto, en la superficie, y los forma pequeños.", "alias": ["Rocas ígneas", "Magmáticas", "Rocas magmáticas", "Ígnea"], "lz": "B"},
  {"n": 390, "q": "¿Qué componentes de la sangre desempeñan un papel fundamental en la coagulación?", "a": "Plaquetas", "cat": "ciencia", "dif": "medio", "alias": ["Trombocitos"], "lz": "A", "sabias": "No son células completas, sino fragmentos de unas células gigantes de la médula ósea, los megacariocitos."},
  {"n": 391, "q": "¿Qué parte coloreada del ojo determina que sea azul, verde o marrón?", "a": "El iris", "cat": "ciencia", "dif": "medio", "sabias": "Su pigmento, la melanina, es lo que marca el color: los ojos azules apenas tienen.", "lz": "A"},
  {"n": 392, "q": "¿Cuál es el gas noble de número atómico 54 que se usa en los motores de iones?", "a": "Xenón", "cat": "ciencia", "dif": "medio", "lz": "A", "sabias": "También se usa en los faros de algunos coches y en lámparas de flash."},
  {"n": 393, "q": "¿Qué tipo de enlaces químicos se forman cuando los átomos comparten pares de electrones de su capa externa?", "a": "Enlaces covalentes", "cat": "ciencia", "dif": "medio", "sabias": "El agua es el ejemplo clásico; en cambio, la sal común se une por enlaces iónicos, que transfieren electrones.", "lz": "B"},
  {"n": 394, "q": "¿Cómo se llama la capa exterior y tenue de la atmósfera del Sol, visible durante un eclipse total?", "a": "Corona solar", "cat": "ciencia", "dif": "dificil", "sabias": "Está a millones de grados, mucho más caliente que la superficie del Sol, y aún se investiga por qué.", "lz": "A", "alias": ["Corona", "La corona"]},
  {"n": 395, "q": "¿Cómo se llama el punto de la órbita de la Luna más alejado de la Tierra?", "a": "Apogeo", "cat": "ciencia", "dif": "dificil", "sabias": "Su distancia a la Tierra oscila entre unos 357.000 y 406.000 km, y por eso la luna llena a veces se ve un 14 % mayor.", "lz": "A"},
  {"n": 396, "q": "¿Qué fenómeno mide la escala de Richter?", "a": "La magnitud de los terremotos", "cat": "ciencia", "dif": "medio", "sabias": "Cada punto más supone unas 32 veces más energía liberada."},
  {"n": 397, "q": "¿Qué telescopio espacial, lanzado en diciembre de 2021, observa el universo sobre todo en infrarrojo?", "a": "Telescopio Espacial James Webb", "cat": "ciencia", "dif": "dificil", "sabias": "Orbita a 1,5 millones de km de la Tierra, cuatro veces más lejos que la Luna.", "lz": "A", "alias": ["James Webb", "JWST", "Telescopio James Webb", "Webb"]},
  {"n": 398, "q": "¿Cómo se llama la unidad de presión del Sistema Internacional?", "a": "Pascal", "cat": "ciencia", "dif": "medio", "sabias": "Es una unidad minúscula: la presión atmosférica normal equivale a 101.325 de ellas.", "alias": ["Pa"], "lz": "A"},
  {"n": 400, "q": "¿Qué neurólogo austriaco es considerado el padre del psicoanálisis?", "a": "Sigmund Freud", "cat": "cultura_general", "dif": "medio", "sabias": "Publicó «La interpretación de los sueños» en 1899, aunque en la portada figura 1900.", "lz": "A"},
  {"n": 402, "q": "¿Cómo se denomina la red ferroviaria de alta velocidad de Japón, inaugurada en 1964?", "a": "Shinkansen", "cat": "cultura_general", "dif": "medio", "sabias": "Su primera línea redujo el trayecto entre Tokio y Osaka de unas seis horas y media a cuatro.", "lz": "A"},
  {"n": 403, "q": "¿Qué inventor serbio-estadounidense impulsó la corriente alterna?", "a": "Nikola Tesla", "cat": "cultura_general", "dif": "medio", "sabias": "Su corriente alterna ganó la «guerra de las corrientes» a la continua de Edison; en 1893 iluminó la Exposición de Chicago.", "lz": "A"},
  {"n": 404, "q": "¿Cómo se denominan los caracteres de origen chino utilizados en la escritura japonesa junto con los kana?", "a": "Kanji", "cat": "cultura_general", "dif": "medio", "sabias": "La palabra «kanji» significa literalmente «caracteres de Han», en referencia a la dinastía china Han.", "lz": "A"},
  {"n": 405, "q": "¿Cómo se llama la fase cálida del fenómeno ENSO, con el Pacífico ecuatorial más caliente de lo normal?", "a": "El Niño", "cat": "ciencia", "dif": "medio", "sabias": "Su nombre alude al Niño Jesús, porque suele aparecer hacia Navidad.", "alias": ["Fenómeno de El Niño"], "lz": "A"},
  {"n": 406, "q": "¿Qué moneda digital descentralizada se atribuye a alguien con el pseudónimo Satoshi Nakamoto?", "a": "Bitcoin", "cat": "cultura_general", "dif": "medio", "sabias": "En 2010 alguien pagó 10.000 bitcoins por dos pizzas.", "lz": "A"},
  {"n": 409, "q": "¿Qué dios nórdico, padre de Thor, sacrificó un ojo a cambio de sabiduría?", "a": "Odín", "cat": "cultura_general", "dif": "medio", "sabias": "De su nombre en inglés, Woden, viene «Wednesday», el día de Odín.", "lz": "A"},
  {"n": 410, "q": "¿Cómo se llama el software malicioso que espía en secreto lo que haces en tu ordenador?", "a": "Spyware", "cat": "cultura_general", "dif": "medio", "sabias": "No todos registran teclas: algunos rastrean hábitos de navegación y otros recopilan datos del dispositivo.", "alias": ["Programa espía"], "lz": "B"},
  {"n": 411, "q": "¿Qué rey babilonio promulgó, hacia el siglo XVIII a. C., uno de los primeros códigos legales escritos?", "a": "Hammurabi", "cat": "historia", "dif": "medio", "sabias": "Incluye la célebre ley del talión: «ojo por ojo».", "alias": ["Rey Hammurabi", "Hamurabi", "Hammurapi"], "lz": "A"},
  {"n": 412, "q": "¿Quién lideró la Revolución cubana que derrocó a Batista en 1959?", "a": "Fidel Castro", "cat": "historia", "dif": "medio", "lz": "A", "sabias": "Desembarcó en la isla en 1956 desde el yate Granma, pensado para doce personas y que cargó con 82."},
  {"n": 413, "q": "¿Quién fue el primer emperador de los franceses?", "a": "Napoleón Bonaparte", "cat": "historia", "dif": "medio", "sabias": "Se coronó él mismo en Notre-Dame en 1804, tomando la corona de manos del papa.", "lz": "A", "alias": ["Napoleón", "Napoleón I"], "par": [23, 339]},
  {"n": 8, "q": "¿Qué científica ganó el Nobel de Física en 1903 y el de Química en 1911?", "a": "Marie Curie", "cat": "ciencia", "dif": "facil", "lz": "B", "sabias": "Fue la primera persona en ganar dos Nobel y la única que los ganó en dos ciencias distintas."},
  {"n": 9, "q": "¿En qué año tuvo lugar el desembarco de Normandía?", "a": "1944", "cat": "historia", "dif": "facil", "sabias": "Fue el mayor desembarco marítimo de la historia, con más de 5.000 barcos.", "lz": "B"},
  {"n": 13, "q": "¿Qué faraón egipcio tuvo una tumba casi intacta descubierta por Howard Carter?", "a": "Tutankamón", "cat": "historia", "dif": "facil", "sabias": "Murió hacia los 19 años y su tumba guardaba más de 5.000 objetos.", "lz": "B"},
  {"n": 18, "q": "¿Qué ciudad romana quedó sepultada por la erupción del Vesubio en el año 79 d. C. bajo cenizas y piedra pómez?", "a": "Pompeya", "cat": "historia", "dif": "facil", "sabias": "Las cenizas conservaron incluso pan en los hornos y grafitis en las paredes.", "lz": "B"},
  {"n": 20, "q": "¿Qué líder sudafricano pasó 27 años en prisión antes de convertirse en presidente del país en 1994?", "a": "Nelson Mandela", "cat": "historia", "dif": "facil", "sabias": "Compartió el Nobel de la Paz de 1993 con Frederik de Klerk.", "lz": "B"},
  {"n": 337, "q": "¿Qué ciudad fue la capital del Imperio bizantino durante más de mil años?", "a": "Constantinopla", "cat": "historia", "dif": "facil", "sabias": "Se cree que «Estambul» deriva del griego «eis tin polin»: «hacia la ciudad».", "lz": "B", "par": [44]},
  {"n": 414, "q": "¿Qué gran escritor ruso es el autor de las monumentales novelas «Guerra y paz» y «Ana Karénina»?", "a": "Lev Tolstói", "cat": "arte_literatura", "dif": "medio", "sabias": "Su esposa, Sofía, copió a mano «Guerra y paz» varias veces.", "lz": "A", "alias": ["Tolstói", "Tolstoi", "León Tolstoi", "Tolstoy"]},
  {"n": 417, "q": "¿Quién pintó la obra «La persistencia de la memoria», famosa por sus relojes blandos?", "a": "Salvador Dalí", "cat": "arte_literatura", "dif": "medio", "sabias": "Dalí contó que los relojes blandos le vinieron al ver derretirse un queso camembert.", "lz": "A"},
  {"n": 419, "q": "¿Qué país alberga la mayor superficie de selva amazónica?", "a": "Brasil", "cat": "geografia", "dif": "medio", "sabias": "Brasil guarda en torno al 60 % de la Amazonia; el resto se reparte entre otros siete países y la Guayana Francesa.", "lz": "B"},
  {"n": 56, "q": "¿Cuál es la capital de Australia?", "a": "Canberra", "cat": "geografia", "dif": "facil", "sabias": "Se construyó desde cero para zanjar la rivalidad entre Sídney y Melbourne.", "lz": "B"},
  {"n": 380, "q": "¿Cuál es la capital de Eslovaquia?", "a": "Bratislava", "cat": "geografia", "dif": "facil", "lz": "B", "sabias": "Está a unos 60 km de Viena: forman una de las parejas de capitales más cercanas de Europa."},
  {"n": 382, "q": "¿Cuál es la capital oficial de Turquía?", "a": "Ankara", "cat": "geografia", "dif": "facil", "lz": "B", "sabias": "Atatürk la proclamó capital en 1923, en lugar de Estambul.", "par": [101]},
  {"n": 420, "q": "¿Qué objeto cósmico tiene una gravedad tan intensa que ni la luz puede escapar de él?", "a": "Agujero negro", "cat": "ciencia", "dif": "medio", "lz": "A", "sabias": "El primero fotografiado fue el de la galaxia M87, en 2019.", "alias": ["Un agujero negro", "Agujeros negros"]},
  {"n": 129, "q": "¿Qué científico descubrió la penicilina en 1928?", "a": "Alexander Fleming", "cat": "ciencia", "dif": "facil", "sabias": "Lo descubrió por casualidad: un moho se coló en una placa de cultivo y mató las bacterias.", "lz": "B"},
  {"n": 133, "q": "¿En qué capa de la atmósfera se concentra la mayor parte del ozono atmosférico?", "a": "Estratosfera", "cat": "ciencia", "dif": "facil", "sabias": "La capa de ozono se extiende entre unos 15 y 35 km de altura.", "lz": "B", "alias": ["La estratosfera"]},
  {"n": 384, "q": "¿Qué instrumento se utiliza para medir la cantidad de precipitación que cae en un lugar?", "a": "Pluviómetro", "cat": "ciencia", "dif": "facil", "lz": "B", "sabias": "Un milímetro de lluvia equivale a un litro de agua por metro cuadrado."},
  {"n": 399, "q": "¿Cuál es el mamífero terrestre más veloz del planeta?", "a": "Guepardo", "cat": "ciencia", "dif": "facil", "alias": ["Chita", "Cheetah"], "lz": "B", "sabias": "Puede pasar de 0 a 100 km/h en unos tres segundos."},
  {"n": 421, "q": "¿Cómo se llama la memoria del ordenador que se borra al apagarlo?", "a": "RAM", "cat": "cultura_general", "dif": "medio", "sabias": "El ordenador de guiado de las misiones Apolo tenía unos 4 KB de RAM: un móvil actual tiene millones de veces más.", "alias": ["Memoria RAM"], "lz": "B"},
  {"n": 282, "q": "¿Cuál es la unidad básica de temperatura termodinámica en el Sistema Internacional?", "a": "Kelvin", "cat": "ciencia", "dif": "facil", "sabias": "0 K equivale a −273,15 °C y es el cero absoluto, la temperatura más baja posible.", "lz": "B", "alias": ["El kelvin"]},
  {"n": 288, "q": "¿Qué rey de la mitología griega convertía en oro todo lo que tocaba?", "a": "El rey Midas", "cat": "cultura_general", "dif": "facil", "lz": "B", "sabias": "Según el mito, se libró del don bañándose en el río Pactolo."},
  {"n": 422, "q": "¿Qué trilogía de Peter Jackson, estrenada entre 2001 y 2003, obtuvo 17 premios Óscar en total?", "a": "El Señor de los Anillos", "cat": "arte_literatura", "dif": "medio", "sabias": "Se rodó en un único rodaje de unos quince meses y la última entrega ganó los 11 Óscar a los que optaba.", "lz": "B", "alias": ["Señor de los Anillos", "The Lord of the Rings"]},
  {"n": 179, "q": "¿Quién creó al detective Sherlock Holmes?", "a": "Arthur Conan Doyle", "cat": "arte_literatura", "dif": "facil", "lz": "B", "sabias": "Doyle lo mató en 1893, en las cataratas de Reichenbach, pero los lectores protestaron tanto que lo resucitó diez años después."},
  {"n": 181, "q": "¿Qué instrumento hawaiano parece una guitarra diminuta de cuatro cuerdas?", "a": "El ukelele", "cat": "arte_literatura", "dif": "facil", "lz": "B", "sabias": "Su nombre suele traducirse como «pulga saltarina»."},
  {"n": 186, "q": "¿Quién escribió La metamorfosis?", "a": "Franz Kafka", "cat": "arte_literatura", "dif": "facil", "lz": "B", "sabias": "Kafka pidió a su amigo Max Brod que quemara su obra al morir; Brod desobedeció y la publicó."},
  {"n": 211, "q": "¿Cómo se denomina una película que cuenta acontecimientos anteriores a los de otra película ya existente?", "a": "Precuela", "cat": "arte_literatura", "dif": "facil", "sabias": "Un ejemplo célebre es «La amenaza fantasma» (1999), que contó hechos anteriores a la trilogía de 1977-1983.", "lz": "B", "alias": ["Una precuela", "Prequel"]},
  {"n": 213, "q": "¿Quién dirigió la película El padrino, estrenada en 1972?", "a": "Francis Ford Coppola", "cat": "arte_literatura", "dif": "facil", "lz": "B", "sabias": "Ganó el Óscar a la mejor película, y Marlon Brando rechazó el suyo."},
  {"n": 424, "q": "¿Qué emperador romano quiso nombrar cónsul a su caballo Incitatus?", "a": "Calígula", "cat": "historia", "dif": "medio", "lz": "A", "sabias": "Según el relato transmitido por Suetonio, Calígula tenía para Incitatus un establo de mármol y un pesebre de marfil."},
  {"n": 425, "q": "¿Qué mercader veneciano narró sus viajes por Asia hasta la corte del Gran Kan?", "a": "Marco Polo", "cat": "historia", "dif": "medio", "lz": "A", "sabias": "Dictó el relato en una cárcel de Génova al escritor Rustichello de Pisa."},
  {"n": 426, "q": "¿Qué caudillo huno fue conocido como el «Azote de Dios»?", "a": "Atila", "cat": "historia", "dif": "medio", "lz": "A", "sabias": "Atila murió en el año 453, tradicionalmente asociado a la noche de su boda."},
  {"n": 427, "q": "¿Qué posición del voleibol está especializada en la recepción y la defensa?", "a": "Líbero", "cat": "deporte", "dif": "medio", "lz": "B", "sabias": "El líbero se incorporó a las reglas internacionales del voleibol en 1998."},
  {"n": 428, "q": "¿Qué bola tiene el mayor valor en el snooker?", "a": "La negra", "cat": "deporte", "dif": "facil", "lz": "B", "alias": ["La bola negra"], "sabias": "El máximo break posible es de 147 puntos: quince rojas con quince negras y luego los seis colores."},
  {"n": 429, "q": "¿En qué deporte se golpea una pelota con un mazo mientras se monta a caballo?", "a": "Polo", "cat": "deporte", "dif": "facil", "lz": "B", "sabias": "Los periodos de juego del polo se llaman chukkers y los jugadores pueden cambiar de caballo durante el partido."},
  {"n": 430, "q": "¿Qué boxeador profesional se retiró con un récord de 50 victorias y ninguna derrota?", "a": "Floyd Mayweather Jr.", "cat": "deporte", "dif": "medio", "lz": "B", "sabias": "Se retiró tras vencer en 2017 a Conor McGregor, campeón de MMA que debutaba como boxeador profesional."},
  {"n": 431, "q": "¿Qué prueba deportiva combina natación, ciclismo y carrera a pie?", "a": "Triatlón", "cat": "deporte", "dif": "facil", "lz": "B", "sabias": "En el triatlón, las tres disciplinas se realizan consecutivamente y el cronómetro no se detiene durante las transiciones."},
  {"n": 432, "q": "¿Qué competición internacional de tenis masculino enfrenta a selecciones nacionales?", "a": "Copa Davis", "cat": "deporte", "dif": "medio", "sabias": "La primera edición de la Copa Davis se disputó en 1900 entre Estados Unidos y Gran Bretaña."},
  {"n": 433, "q": "¿En qué deporte de invierno se desciende en un pequeño trineo tumbado boca abajo y con la cabeza por delante?", "a": "Skeleton", "cat": "deporte", "dif": "medio", "lz": "A", "sabias": "Se baja a más de 120 km/h con la cara a pocos centímetros del hielo y sin frenos."},
  {"n": 434, "q": "¿Cómo se llama el cambio aparente de frecuencia de un sonido cuando su fuente se acerca o se aleja del observador?", "a": "Efecto Doppler", "cat": "ciencia", "dif": "medio", "lz": "A", "sabias": "La sirena de una ambulancia suele percibirse más aguda al acercarse y más grave al alejarse."},
  {"n": 435, "q": "¿Qué principio explica que un cuerpo sumergido en un fluido experimente un empuje hacia arriba?", "a": "Principio de Arquímedes", "cat": "ciencia", "dif": "medio", "lz": "A", "alias": ["Ley de Arquímedes"], "sabias": "Un submarino se hunde o emerge llenando de agua o de aire sus tanques de lastre: cambia su peso, no su volumen."},
  {"n": 436, "q": "¿Qué sistema representa letras y números mediante puntos y rayas?", "a": "Código Morse", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "Aún hoy las radiobalizas de navegación aérea se identifican con unas pocas letras emitidas en este código."},
  {"n": 437, "q": "¿Cómo se llama una palabra que se lee igual de izquierda a derecha que de derecha a izquierda?", "a": "Palíndromo", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "«Anita lava la tina» y «Dábale arroz a la zorra el abad» son dos palíndromos clásicos del español."},
  {"n": 438, "q": "¿Quién pintó la obra El grito?", "a": "Edvard Munch", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "Dos de sus versiones fueron robadas de museos noruegos, en 1994 y en 2004; ambas se recuperaron."},
  {"n": 439, "q": "¿Qué película surcoreana se convirtió en la primera película en lengua no inglesa en ganar el Óscar a mejor película?", "a": "Parásitos", "cat": "arte_literatura", "dif": "medio", "lz": "A", "sabias": "La película de Bong Joon-ho ganó cuatro Óscar en la ceremonia de 2020, incluido el de mejor película."},
  {"n": 440, "q": "¿Qué pieza de ajedrez se mueve en forma de L y puede saltar sobre otras piezas?", "a": "El caballo", "cat": "deporte", "dif": "facil", "lz": "B", "sabias": "El caballo es la única pieza de ajedrez que puede saltar por encima de otras."},
  {"n": 441, "q": "¿A qué reino pertenecen las levaduras y las setas?", "a": "Al reino de los hongos", "cat": "ciencia", "dif": "medio", "lz": "A", "alias": ["Reino Fungi", "Fungi"], "sabias": "Un hongo, Armillaria ostoyae, ocupa unos 9,6 km² en un bosque de Oregón y es uno de los mayores seres vivos conocidos."},
  {"n": 442, "q": "¿Qué planeta del sistema solar es famoso por su sistema de anillos?", "a": "Saturno", "cat": "ciencia", "dif": "facil", "lz": "B", "sabias": "Se extienden unos 280.000 km, pero su grosor suele ser de apenas diez metros."},
  {"n": 443, "q": "¿En qué país se encuentra el Salto Ángel, la cascada más alta del mundo?", "a": "Venezuela", "cat": "geografia", "dif": "medio", "lz": "A", "sabias": "Lleva el nombre del piloto estadounidense Jimmie Angel, que lo sobrevoló en 1933 buscando una mina de oro."},
  {"n": 444, "q": "¿Qué disciplina se ocupa de la elaboración, el estudio y el uso de los mapas?", "a": "Cartografía", "cat": "cultura_general", "dif": "medio", "lz": "A", "sabias": "El término «cartografía» se acuñó en 1839."},
  {"n": 445, "q": "¿Qué dios romano, representado con dos caras, estaba asociado a los comienzos y las transiciones?", "a": "Jano", "cat": "historia", "dif": "medio", "lz": "A", "alias": ["Janus"], "sabias": "El nombre del mes de enero procede de Jano, relacionado con los comienzos."},
  {"n": 446, "q": "¿Cuántos corazones tiene un pulpo?", "a": "Tres", "cat": "ciencia", "dif": "medio", "lz": "B", "alias": ["3"], "sabias": "Dos corazones bombean sangre hacia las branquias y el tercero la impulsa al resto del cuerpo."},
  {"n": 447, "q": "¿Qué hallazgo fue clave para descifrar los jeroglíficos egipcios?", "a": "La piedra de Rosetta", "cat": "historia", "dif": "medio", "lz": "A", "sabias": "La piedra contiene un mismo decreto en escritura jeroglífica, demótica y griego antiguo."},
  {"n": 448, "q": "¿Cómo se llama el arte japonés de doblar papel para crear figuras?", "a": "Origami", "cat": "arte_literatura", "dif": "facil", "lz": "B", "sabias": "Según la tradición japonesa, quien dobla mil grullas, el «senbazuru», ve cumplido un deseo."},
  {"n": 449, "q": "¿Qué ave puede volar hacia atrás de forma sostenida y controlada?", "a": "El colibrí", "cat": "ciencia", "dif": "medio", "lz": "A", "alias": ["Picaflor"], "sabias": "Aletea entre 50 y 80 veces por segundo y su corazón puede superar los 1.000 latidos por minuto."},
  {"n": 450, "q": "¿Cuál es el hueso más pequeño del cuerpo humano?", "a": "El estribo", "cat": "ciencia", "dif": "medio", "lz": "A", "sabias": "El estribo está en el oído medio y mide aproximadamente tres milímetros."},
  {"n": 451, "q": "¿Qué mamífero es conocido por tener huellas dactilares muy parecidas a las humanas?", "a": "El koala", "cat": "ciencia", "dif": "medio", "sabias": "Duermen hasta 20 horas al día: las hojas de eucalipto dan poca energía y ahorrarla es vital."},
  {"n": 452, "q": "¿Qué mar del océano Atlántico está delimitado por corrientes oceánicas y no por costas?", "a": "El mar de los Sargazos", "cat": "geografia", "dif": "dificil", "lz": "A", "sabias": "Allí desovan las anguilas europeas y americanas, tras recorrer miles de kilómetros."},
  {"n": 453, "q": "¿En qué antigua civilización se desarrolló la fabricación de papel tradicionalmente atribuida a Cai Lun?", "a": "China", "cat": "historia", "dif": "facil", "lz": "B", "alias": ["La antigua China"], "sabias": "Según la tradición, los árabes aprendieron a fabricar papel de prisioneros chinos tras la batalla de Talas, en el 751."},
  {"n": 454, "q": "¿En qué disciplina se concede el Premio Pritzker?", "a": "Arquitectura", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": ["La arquitectura"], "par": [468], "sabias": "Lo creó la familia Pritzker, dueña de la cadena de hoteles Hyatt, y el primer premiado fue Philip Johnson, en 1979."},
  {"n": 455, "q": "¿En qué disciplina se concede la Medalla Fields?", "a": "Matemáticas", "cat": "ciencia", "dif": "dificil", "lz": "A", "alias": ["Las matemáticas"], "sabias": "Se entrega cada cuatro años y sus destinatarios deben tener menos de 40 años el 1 de enero del año del congreso correspondiente."},
  {"n": 456, "q": "¿De qué color son las llamadas cajas negras de los aviones?", "a": "Naranjas", "cat": "cultura_general", "dif": "dificil", "lz": "A", "alias": ["Naranja", "Anaranjado", "Anaranjadas"], "sabias": "Cada avión lleva dos: una graba los datos de vuelo y la otra, las voces y los sonidos de la cabina."},
  {"n": 457, "q": "¿Qué mujer es considerada una pionera de la programación informática por su trabajo en el siglo XIX?", "a": "Ada Lovelace", "cat": "cultura_general", "dif": "dificil", "lz": "A", "alias": ["Lovelace", "Ada Byron"], "sabias": "Ada Lovelace imaginó que las máquinas de cálculo podrían manipular símbolos y hasta componer música, no solo números."},
  {"n": 458, "q": "¿Qué empresa tecnológica fundó Steve Jobs en 1985 tras abandonar Apple?", "a": "NeXT", "cat": "cultura_general", "dif": "dificil", "lz": "A", "alias": ["NeXT Computer"], "sabias": "Apple adquirió NeXT en 1996. La tecnología de su sistema operativo contribuyó a la base de los sistemas modernos de Apple."},
  {"n": 459, "q": "¿A qué objeto se refiere propiamente el nombre Big Ben en Londres?", "a": "A la gran campana del reloj", "cat": "cultura_general", "dif": "dificil", "lz": "B", "alias": ["La campana", "La gran campana", "Una campana", "Campana"], "sabias": "La torre que alberga el reloj se llama oficialmente Elizabeth Tower desde 2012."},
  {"n": 460, "q": "¿Cuál es la especia que suele considerarse la más cara del mundo por peso?", "a": "El azafrán", "cat": "cultura_general", "dif": "dificil", "lz": "A", "alias": ["Azafrán"], "sabias": "Para obtener un kilo de azafrán seco hacen falta unas 150.000 flores, cuyos estigmas se separan a mano."},
  {"n": 461, "q": "¿Qué significan realmente las letras de la señal de socorro SOS?", "a": "No son siglas; se eligió por su patrón Morse", "cat": "cultura_general", "dif": "dificil", "alias": ["Nada", "No son siglas", "Nada, no son siglas"], "sabias": "Se adoptó en 1906 y sustituyó al CQD, la señal anterior; en 1912 un gran transatlántico emitió ambas a la vez."},
  {"n": 462, "q": "¿Qué lengua internacional artificial creó Ludwik Zamenhof y presentó en 1887?", "a": "Esperanto", "cat": "cultura_general", "dif": "dificil", "lz": "A", "alias": ["El esperanto"], "sabias": "Zamenhof publicó su propuesta bajo el seudónimo Doktoro Esperanto, expresión que significa aproximadamente «doctor que espera»."},
  {"n": 463, "q": "¿Cómo se llama el trofeo que recibe el campeón de la liga profesional norteamericana de hockey sobre hielo (NHL)?", "a": "Copa Stanley", "cat": "deporte", "dif": "dificil", "lz": "A", "alias": ["La Copa Stanley", "Stanley Cup", "Stanley"], "sabias": "La donó en 1892 Lord Stanley, entonces gobernador general, para premiar al mejor equipo amateur."},
  {"n": 464, "q": "¿Cuál es la máxima puntuación posible con tres dardos en un turno?", "a": "180", "cat": "deporte", "dif": "dificil", "lz": "A", "alias": ["Ciento ochenta"], "sabias": "El «nine-darter», 501 puntos en solo nueve dardos, suele ser 180, 180 y 141: triple 20, triple 19 y doble 12 al final."},
  {"n": 465, "q": "¿A qué altura se encuentra el borde superior del aro de una canasta de baloncesto respecto al suelo?", "a": "3,05 metros", "cat": "deporte", "dif": "dificil", "lz": "A", "alias": ["3,05", "3.05", "3,05 m", "3,05 metros", "10 pies", "Diez pies"], "sabias": "James Naismith colgó en 1891 dos cestos de melocotones a 10 pies, y esa medida no ha cambiado en más de un siglo."},
  {"n": 466, "q": "¿Qué atleta estadounidense popularizó una técnica de salto de altura de espaldas al listón en los Juegos de 1968?", "a": "Dick Fosbury", "cat": "deporte", "dif": "dificil", "lz": "A", "alias": ["Fosbury"], "sabias": "Ganó el oro en esos Juegos con 2,24 m, y su estilo solo fue seguro gracias a las nuevas colchonetas de espuma."},
  {"n": 467, "q": "¿Quién pintó el tríptico conocido como El jardín de las delicias?", "a": "El Bosco", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": ["Bosco", "Bosch", "Hieronymus Bosch", "Jheronimus Bosch"], "sabias": "Cerrado, el tríptico muestra por fuera una esfera en grisalla: la Tierra en el tercer día de la Creación."},
  {"n": 468, "q": "¿Qué arquitecto diseñó el Museo Guggenheim de Bilbao?", "a": "Frank Gehry", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": ["Gehry", "Frank O. Gehry"], "par": [454], "sabias": "El museo abrió en 1997 y es conocido por sus formas curvas y su revestimiento de titanio."},
  {"n": 469, "q": "¿Cómo se llama el sistema inca de cuerdas y nudos que se utilizaba para registrar información?", "a": "Quipu", "cat": "historia", "dif": "dificil", "lz": "A", "alias": ["El quipu"], "sabias": "Los quipus guardaban cantidades con cuerdas, nudos y colores; aún se investiga si también registraban relatos."},
  {"n": 470, "q": "¿Cómo se llamó la alianza de ciudades comerciales del norte de Europa que tuvo gran influencia en el Báltico durante la Edad Media?", "a": "Liga Hanseática", "cat": "historia", "dif": "dificil", "lz": "A", "alias": ["La Liga Hanseática", "Hansa", "La Hansa"], "sabias": "«Hansa» significa «grupo» o «compañía» en alemán antiguo, y su ciudad principal fue Lübeck."},
  {"n": 471, "q": "¿Cuál es el elemento químico más abundante en la corteza terrestre en masa?", "a": "Oxígeno", "cat": "ciencia", "dif": "dificil", "lz": "A", "alias": ["El oxígeno"], "sabias": "El oxígeno representa aproximadamente el 46 % de la masa de la corteza terrestre, principalmente formando parte de minerales y silicatos."},
  {"n": 472, "q": "¿Cómo se llaman los organismos cuyas células carecen de un núcleo delimitado por una membrana?", "a": "Procariotas", "cat": "ciencia", "dif": "dificil", "lz": "A", "alias": ["Procariota", "Células procariotas"], "sabias": "Fueron los únicos seres vivos durante más de mil millones de años, hasta que aparecieron las células con núcleo."},
  {"n": 473, "q": "¿Qué astrónomo aportó pruebas observacionales decisivas de que existían galaxias más allá de la Vía Láctea?", "a": "Edwin Hubble", "cat": "ciencia", "dif": "dificil", "lz": "A", "alias": ["Hubble"], "sabias": "Hubble usó estrellas cefeidas en los años 20 para demostrar que la nebulosa de Andrómeda está fuera de la Vía Láctea."},
  {"n": 474, "q": "¿Qué país posee más husos horarios del mundo gracias a sus territorios de ultramar?", "a": "Francia", "cat": "geografia", "dif": "dificil", "lz": "A", "sabias": "Con sus territorios repartidos por todos los océanos, Francia reúne 12 husos horarios, más que Rusia (11) o Estados Unidos (11)."},
  {"n": 475, "q": "¿Qué río atraviesa diez países, más que ningún otro del mundo?", "a": "El Danubio", "cat": "geografia", "dif": "dificil", "lz": "A", "alias": ["Danubio"], "sabias": "Su nombre procede de una antigua raíz indoeuropea que significa «río», la misma de ríos como el Don, el Dniéper y el Dniéster."},
  {"n": 476, "q": "¿Qué estrecho separa la isla de Sicilia de la península italiana?", "a": "Estrecho de Mesina", "cat": "geografia", "dif": "dificil", "lz": "A", "alias": ["Mesina", "El estrecho de Mesina", "Messina"], "par": [493], "sabias": "En su punto más angosto mide unos 3 kilómetros; en la mitología se asocia con los monstruos Escila y Caribdis."},
  {"n": 477, "q": "¿Qué pintor neerlandés realizó «La joven de la perla»?", "a": "Johannes Vermeer", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": ["Vermeer", "Jan Vermeer"], "sabias": "El cuadro se conserva en el Mauritshuis de La Haya y se le llama a veces «la Mona Lisa del Norte»."},
  {"n": 478, "q": "¿Quién unificó China en 221 a. C. y se proclamó su primer emperador?", "a": "Qin Shi Huang", "cat": "historia", "dif": "dificil", "lz": "A", "alias": ["Qin Shi Huangdi", "Shi Huangdi"], "sabias": "Su mausoleo, cerca de Xi'an, está custodiado por miles de soldados de terracota."},
  {"n": 479, "q": "¿Qué emperador romano instauró hacia el año 293 la Tetrarquía, un gobierno compartido entre cuatro gobernantes?", "a": "Diocleciano", "cat": "historia", "dif": "dificil", "lz": "A", "sabias": "Diocleciano fue uno de los pocos emperadores romanos que abdicaron voluntariamente; se retiró a vivir a su palacio de Split."},
  {"n": 480, "q": "¿Qué institución concede cada año el Premio Nobel de la Paz?", "a": "El Comité Noruego del Nobel", "cat": "cultura_general", "dif": "dificil", "lz": "B", "alias": ["Comité Noruego del Nobel", "El Comité Noruego", "Comité Noruego"], "sabias": "Es el único Nobel que se entrega en Oslo; los demás se entregan en Estocolmo, por voluntad de Alfred Nobel."},
  {"n": 481, "q": "¿Qué compañía lanzó en 1988 la consola Mega Drive, llamada Genesis en Norteamérica?", "a": "Sega", "cat": "cultura_general", "dif": "dificil", "lz": "A", "sabias": "Su mascota, Sonic, nació en 1991 para competir con Mario, de Nintendo."},
  {"n": 482, "q": "¿Cuál es el río más largo de Asia?", "a": "El Yangtsé", "cat": "geografia", "dif": "dificil", "lz": "A", "alias": ["Yangtsé", "Yangtze", "El Yangtze", "Río Yangtsé", "Chang Jiang"], "sabias": "Con unos 6.300 kilómetros de longitud, atraviesa China de oeste a este hasta desembocar en el mar de China Oriental, cerca de Shanghái."},
  {"n": 483, "q": "¿En qué deporte se concede cada año el trofeo Heisman?", "a": "Fútbol americano universitario", "cat": "deporte", "dif": "dificil", "lz": "A", "alias": ["Fútbol americano", "Fútbol americano de universidad"], "sabias": "Su nombre es el del entrenador John Heisman, cuyo equipo ganó 222-0 en 1916, la mayor goleada de la historia del fútbol americano."},
  {"n": 484, "q": "¿Qué compositor alemán es el autor de la cantata escénica «Carmina Burana»?", "a": "Carl Orff", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": ["Orff"], "sabias": "Se estrenó en 1937 y su fragmento inicial, «O Fortuna», es una de las piezas corales más utilizadas en el cine y la publicidad."},
  {"n": 485, "q": "¿Qué pueblo del Mediterráneo oriental fundó la ciudad de Cartago?", "a": "Los fenicios", "cat": "historia", "dif": "dificil", "lz": "A", "alias": ["Fenicios", "Fenicia"], "sabias": "Según la tradición, la reina Dido, procedente de Tiro, la fundó hacia el año 814 a. C."},
  {"n": 486, "q": "¿Qué dos casas se disputaron el trono de Inglaterra en la Guerra de las Dos Rosas?", "a": "Lancaster y York", "cat": "historia", "dif": "dificil", "lz": "A", "alias": ["York y Lancaster", "Casas de Lancaster y York"], "sabias": "El conflicto se dio por cerrado con la victoria de Enrique Tudor en Bosworth (1485); al casarse con Isabel de York unió ambas casas."},
  {"n": 487, "q": "¿Cuál es el mayor desierto del mundo por superficie, contando los polares?", "a": "El desierto Antártico", "cat": "geografia", "dif": "dificil", "lz": "B", "alias": ["La Antártida", "Antártida", "Desierto Antártico"], "sabias": "Con unos 14 millones de km², la Antártida es un desierto por sus escasísimas precipitaciones."},
  {"n": 488, "q": "¿Cuál es el país más pequeño de Asia por superficie?", "a": "Maldivas", "cat": "geografia", "dif": "dificil", "lz": "A", "alias": ["Las Maldivas"], "sabias": "Ocupa unos 300 km² repartidos en cerca de 1.200 islas coralinas."},
  {"n": 489, "q": "¿Qué ciclista belga, apodado «el Caníbal», ganó cinco Tours de Francia?", "a": "Eddy Merckx", "cat": "deporte", "dif": "dificil", "lz": "A", "alias": ["Merckx"], "sabias": "Ganó los Tours de 1969 a 1972 y el de 1974; su apodo viene de su hambre de victorias."},
  {"n": 490, "q": "¿Qué escudería de Fórmula 1 ha ganado más títulos de constructores?", "a": "Ferrari", "cat": "deporte", "dif": "dificil", "lz": "A", "alias": ["Scuderia Ferrari"], "sabias": "Su fundador la creó en 1929 para correr con coches de Alfa Romeo; el primer coche propio llegó en 1947."},
  {"n": 491, "q": "¿Qué pintor austriaco realizó «El beso», de 1907-1908?", "a": "Gustav Klimt", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": ["Klimt"], "sabias": "El cuadro, con abundante pan de oro, se conserva en el Belvedere de Viena."},
  {"n": 492, "q": "¿Cuál es el planeta más denso del sistema solar?", "a": "La Tierra", "cat": "ciencia", "dif": "dificil", "lz": "A", "alias": ["Tierra"], "sabias": "Saturno es tan poco denso que, en teoría, flotaría en un océano lo bastante grande."},
  {"n": 493, "q": "¿Cuál es la isla más grande del mar Mediterráneo?", "a": "Sicilia", "cat": "geografia", "dif": "dificil", "lz": "A", "par": [476], "sabias": "Con unos 25.700 km², supera a Cerdeña, que es la segunda."},
  {"n": 494, "q": "¿Cuál es la capital de Eslovenia?", "a": "Liubliana", "cat": "geografia", "dif": "dificil", "lz": "A", "alias": ["Ljubljana"], "sabias": "Su símbolo es un dragón, que corona el Puente del Dragón y aparece en el escudo de la ciudad."},
  {"n": 495, "q": "¿Qué portero es el único que ha ganado el Balón de Oro, en 1963?", "a": "Lev Yashin", "cat": "deporte", "dif": "dificil", "lz": "A", "alias": ["Yashin", "Lev Yachin", "Yachin"], "sabias": "Lo llamaban «la Araña Negra» por su uniforme oscuro y su agilidad."},
  {"n": 496, "q": "¿Cómo se llama el alfabeto que usan idiomas como el ruso y el búlgaro?", "a": "El alfabeto cirílico", "cat": "cultura_general", "dif": "dificil", "lz": "A", "alias": ["Cirílico", "Alfabeto cirílico"], "sabias": "No lo inventó san Cirilo, sino sus discípulos hacia el siglo X; él creó antes otro alfabeto eslavo, el glagolítico."},
  {"n": 497, "q": "¿Cuál es la capa más externa de la atmósfera terrestre?", "a": "La exosfera", "cat": "ciencia", "dif": "dificil", "lz": "A", "alias": ["Exosfera"], "sabias": "Se extiende desde unos 700 km de altura y se funde gradualmente con el espacio."},
  {"n": 498, "q": "¿Qué animal tiene el cerebro más grande de la Tierra?", "a": "El cachalote", "cat": "ciencia", "dif": "dificil", "lz": "A", "alias": ["Cachalote"], "sabias": "Puede bucear a más de 1.000 m de profundidad y aguantar más de una hora sin respirar."},
  {"n": 499, "q": "¿Qué hormona regula el ritmo del sueño y se segrega en la glándula pineal?", "a": "La melatonina", "cat": "ciencia", "dif": "dificil", "lz": "A", "alias": ["Melatonina"], "sabias": "Se produce sobre todo de noche; la luz de las pantallas puede frenar su liberación."},
  {"n": 500, "q": "¿Qué país del mundo tiene más pirámides?", "a": "Sudán", "cat": "geografia", "dif": "dificil", "lz": "B", "alias": ["El Sudán"], "sabias": "Tiene más de 200, la mayoría de la civilización kushita, y más que Egipto."},
  {"n": 501, "q": "¿Cuál es el país más poblado de África?", "a": "Nigeria", "cat": "geografia", "dif": "dificil", "lz": "A", "sabias": "Se hablan más de 500 lenguas, y la capital es Abuya, no Lagos, la ciudad más grande."},
  {"n": 502, "q": "¿Qué dibujante argentino creó a Mafalda?", "a": "Quino", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": ["Joaquín Salvador Lavado"], "sabias": "La tira nació en 1964; su autor se llamaba Joaquín Salvador Lavado."},
  {"n": 503, "q": "¿Por qué los alimentos tardan más en cocerse en lo alto de una montaña?", "a": "Porque el agua hierve a menos temperatura", "cat": "ciencia", "dif": "dificil", "sabias": "A 3.000 m de altura el agua hierve a unos 90 °C; por eso se usa olla a presión."},
  {"n": 545, "q": "¿Cómo se llama el recurso que muestra al inicio una escena de más adelante en la historia?", "a": "Flashforward", "cat": "arte_literatura", "dif": "dificil", "lz": "A", "alias": ["Flash forward", "Un flashforward", "Flash-forward", "Prolepsis"], "sabias": "Si en cambio se salta a un momento anterior al presente de la historia, se llama flashback."},
  {"n": 558, "q": "¿Qué instrumento de percusión llegó al flamenco desde Perú?", "a": "El cajón", "cat": "arte_literatura", "dif": "medio", "lz": "A", "alias": ["Cajón", "El cajón peruano", "Cajón peruano", "Cajón flamenco"], "sabias": "Paco de Lucía lo conoció en un viaje a Perú en 1977 y lo incorporó a su grupo; hoy acompaña al flamenco."},
  {"n": 560, "q": "¿A qué familia de instrumentos pertenecen el oboe y el fagot?", "a": "Viento-madera", "cat": "arte_literatura", "dif": "medio", "lz": "B", "alias": ["Viento madera", "Maderas", "Instrumentos de viento-madera"], "sabias": "Se clasifican por cómo suenan, no por el material: la flauta travesera, aunque sea de metal, es viento-madera."},
  {"n": 566, "q": "¿Qué reacción contribuye al color y aroma de la corteza del pan al hornearlo?", "a": "La reacción de Maillard", "cat": "cultura_general", "dif": "dificil", "lz": "A", "alias": ["Maillard", "Reacción de Maillard", "Reacción Maillard"], "sabias": "Lleva el nombre del químico francés Louis-Camille Maillard, que la describió en 1912 al calentar aminoácidos con azúcares."},
  {"n": 571, "q": "¿Qué ingrediente da al mochi japonés su textura elástica?", "a": "Arroz glutinoso", "cat": "cultura_general", "dif": "medio", "lz": "A", "alias": ["El arroz glutinoso", "Arroz pegajoso", "Mochigome"], "sabias": "Pese a su nombre, el arroz glutinoso no tiene gluten: su textura pegajosa viene de la amilopectina."},
  {"n": 585, "q": "¿Qué tipo de escritura usa un signo para cada sílaba?", "a": "Un silabario", "cat": "cultura_general", "dif": "medio", "lz": "A", "alias": ["Silabario", "El silabario"], "sabias": "El kana japonés es un silabario; en rigor representa moras, una unidad algo más precisa que la sílaba."},
  {"n": 590, "q": "En baloncesto, ¿qué infracción comete quien, con el balón controlado, da más apoyos de los permitidos sin botarlo?", "a": "Pasos", "cat": "deporte", "dif": "medio", "lz": "B", "alias": ["Los pasos", "Marcha", "Viaje"], "sabias": "Tras recibir o parar el bote se permiten dos apoyos; el pie de pivote no puede moverse del suelo."},
];;

